-- e50b1bee English: The selected profile changed. Reopen the import window.
[1355] = "Il profilo selezionato è cambiato. Riapri la finestra di importazione.",
-- 1609b3f3 English: This import contains Lua code. Only continue if you trust its author. Import
--     opens the code for review; saving the condition can execute it.
[1356] = "Questa importazione contiene codice Lua. Continua solo se ti fidi del suo autore. Importa apre il codice per esaminarlo; salvare la condizione può eseguirlo.",
-- ae820bc2 English: Use letters, numbers and underscores for the condition identifier.
[1357] = "Usa lettere, numeri e trattini bassi per l'identificativo della condizione.",
