-- 8e09cadd English: Check syntax
[1359] = "Verifica sintassi",
-- 1ae4fec7 English: Choose icon
[1360] = "Scegli icona",
-- 18156f45 English: Custom Lua has the same access as the addon. Only import code you trust. Syntax
--     validation cannot establish that a callback is safe or correct. Existing custom widget
--     callbacks still use their original UI contract.
[1361] = "Il Lua personalizzato ha lo stesso accesso dell'addon. Importa solo codice di cui ti fidi. La verifica della sintassi non può stabilire se una callback sia sicura o corretta. Le callback esistenti dei widget personalizzati usano ancora il loro contratto di interfaccia originale.",
-- a53c11ee English: Declare named fields, primitive types, nested records and unions. Example: {
--     spell = { string, number }, unit = string, tests = condition[] }. Schema text is parsed as
--     data and never evaluated as Lua.
[1362] = "Dichiara campi con nome, tipi primitivi, record annidati e unioni. Esempio: { spell = { string, number }, unit = string, tests = condition[] }. Il testo dello schema viene interpretato come dati e non viene mai eseguito come Lua.",
