[1377] = "Modifica descrizione, tag, autore, reame, e-mail, sito web e versione. Le citazioni delle fonti restano separate dalla tua attribuzione. Usa modifiche aggiorna la bozza della rotazione; applica la rotazione per salvarla. Annulla o Esc ripristina i valori che questa finestra aveva all'apertura.",
-- 73f5fe1e English: Invalid tags. Use up to 64 tags of 64 characters, separated by commas.
[1378] = "Tag non validi. Usa fino a 64 tag di 64 caratteri, separati da virgole.",
-- 36b7b9b3 English: Separate tags with commas. Use quotes for tags containing commas. Any personal
--     label is allowed.
[1379] = "Separa i tag con virgole. Usa le virgolette per i tag che contengono virgole. È consentita qualsiasi etichetta personale.",
