[1383] = "Priorità non valida",
-- 1501b340 English: Switch priority must be a whole number between -100000 and 100000.
[1384] = "La priorità di cambio deve essere un numero intero compreso tra -100000 e 100000.",
-- f3967731 English: Edit the description, tags, switch priority, author, realm, email, website and
--     version. Source citations remain separate from your attribution. Use changes updates the
--     rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s
--     opening values.
[1385] = "Modifica descrizione, tag, priorità di cambio, autore, reame, e-mail, sito web e versione. Le citazioni delle fonti restano separate dalla tua attribuzione. Usa modifiche aggiorna la bozza della rotazione; applica la rotazione per salvarla. Annulla o Esc ripristina i valori che questa finestra aveva all'apertura.",
-- a37462ad English: Higher numbers are tried first; your rotations and Built Ins compete on
--     priority alone. The fallback is used only when no other rotation matches. Equal priorities
--     use name, then identity. Blank means zero.
[1386] = "I numeri più alti vengono provati per primi; le tue rotazioni e quelle integrate competono solo sulla priorità. La rotazione di riserva viene usata solo quando nessun'altra rotazione corrisponde. A parità di priorità decidono il nome, poi l'identità. Vuoto significa zero.",
-- 2040fdbd English: Invalid switch priority for %s:%s; explicit repair resets it to zero.
[1387] = "Priorità di cambio non valida per %s:%s; una riparazione esplicita la riporta a zero.",
