--     its field order. Advanced exposes the equivalent raw schema, parsed as data without executing
--     Lua.
[1577] = "Modifica campi apre una bozza grafica dello schema. Aggiungi, rinomina, riordina o rimuovi campi, scegli tipi primitivi o annidati e modifica i campi annidati. Applica prepara lo schema e l'ordine dei suoi campi. Avanzate mostra lo schema grezzo equivalente, interpretato come dati senza eseguire Lua.",
-- 5ed7c1f2 English: Decide whether this condition currently matches.
[1578] = "Stabilisce se questa condizione è attualmente soddisfatta.",
-- cbb89125 English: The stored values for this condition.
[1579] = "I valori memorizzati per questa condizione.",
-- d02f326b English: Shared data for this evaluation cycle.
[1580] = "Dati condivisi per questo ciclo di valutazione.",
-- 5e32b652 English: Evaluation start time, in seconds from GetTime().
[1581] = "Istante di inizio della valutazione, in secondi da GetTime().",
-- dbb95241 English: True matches; false or nil does not match.
[1582] = "true corrisponde; false o nil non corrisponde.",
-- 33035e0c English: Check whether the stored condition values are complete and valid.
[1583] = "Controlla se i valori memorizzati della condizione sono completi e validi.",
-- bc51adc0 English: Rotation specialization scope.
[1584] = "Ambito di specializzazione della rotazione.",
-- 0cb1ce78 English: True when the condition can be evaluated.
[1585] = "true quando la condizione può essere valutata.",
-- 18eb8e30 English: Describe the condition in readable words.
[1586] = "Descrive la condizione a parole.",
-- 4e9300c4 English: The human-readable condition summary.
[1587] = "Il riepilogo leggibile della condizione.",
-- 7ea336df English: Build the controls used to edit this condition.
[1588] = "Crea i controlli usati per modificare questa condizione.",
-- 2010cda9 English: The condition field container supplied by the UI adapter.
[1589] = "Il contenitore dei campi della condizione fornito dall'adattatore dell'interfaccia.",
-- 2209776b English: Add controls to the supplied container.
[1590] = "Aggiunge i controlli al contenitore fornito.",
-- ca5a0eaf English: Build the help content for this condition.
[1591] = "Crea il contenuto dell'aiuto per questa condizione.",
-- a2731a25 English: The help container supplied by the UI adapter.
[1592] = "Il contenitore dell'aiuto fornito dall'adattatore dell'interfaccia.",
-- 96bf1d1e English: Add help content to the supplied container.
[1593] = "Aggiunge il contenuto dell'aiuto al contenitore fornito.",
-- 6738aee6 English: Initialize resources when the condition is registered.
[1594] = "Inizializza le risorse quando la condizione viene registrata.",
-- 49e57f5b English: The condition identifier.
[1595] = "L'identificativo della condizione.",
-- 46569f1f English: No return value is used.
[1596] = "Il valore restituito non viene usato.",
-- 95a1b634 English: Release resources when the condition is removed or replaced.
[1597] = "Rilascia le risorse quando la condizione viene rimossa o sostituita.",
-- 7f816072 English: Arguments
[1598] = "Argomenti",
-- 16dcaa92 English: Returns
[1599] = "Valori restituiti",
-- b92993e1 English: Field names are Lua identifiers. Choose a field type from its dropdown. Records
--     contain named fields; allowed types contain alternatives, including nested records.
[1600] = "I nomi dei campi sono identificatori Lua. Scegli il tipo di un campo dal suo menu a tendina. I record contengono campi con nome; i tipi consentiti contengono alternative, inclusi record annidati.",
-- 5f81b556 English: A container carries its nested fields. Drop into a highlighted gap. Up / Down
--     moves within the current container; Duplicate copies the complete field; the red trash can
--     deletes it.
[1601] = "Un contenitore porta con sé i suoi campi annidati. Rilascia in uno spazio evidenziato. Su / Giù sposta all'interno del contenitore attuale; Duplica copia il campo completo; il cestino rosso lo elimina.",
-- d24ed6ad English: The chevron hides or shows nested fields. Add field appends to that container.
--     Undo / Redo affect the draft. Apply validates and stages the schema; Cancel leaves the
--     condition unchanged. Red borders mark invalid names or incomplete types.
[1602] = "La freccia nasconde o mostra i campi annidati. Aggiungi campo aggiunge in fondo a quel contenitore. Annulla / Ripeti agiscono sulla bozza. Applica convalida e prepara lo schema; Annulla lascia invariata la condizione. I bordi rossi indicano nomi non validi o tipi incompleti.",
-- 521fc51f English: Packaged helper from %s.
[1603] = "Funzione di supporto inclusa da %s.",
-- 75e942e5 English: Functions
[1604] = "Funzioni",
-- 786697a7 English: Browse packaged helpers and edit reusable custom Lua functions.
[1605] = "Sfoglia le funzioni di supporto incluse e modifica funzioni Lua personalizzate riutilizzabili.",
-- fc6e1f0d English: Function unavailable: %s
[1606] = "Funzione non disponibile: %s",
-- 2abb9d73 English: Argument name
[1607] = "Nome dell'argomento",
-- 6956b2bc English: Add argument
[1608] = "Aggiungi argomento",
-- b38d87b4 English: Add return
[1609] = "Aggiungi valore restituito",
-- 355cc18a English: Built-in function
[1610] = "Funzione integrata",
-- 0d1f23b5 English: Custom function
[1611] = "Funzione personalizzata",
-- 4dcab896 English: Delete this function? Existing dependents will become unavailable.
[1612] = "Vuoi eliminare questa funzione? Gli elementi che ne dipendono diventeranno non disponibili.",
-- 3ac00ae7 English: Deletion staged. Apply to remove this function.
[1613] = "Eliminazione preparata. Applica per rimuovere questa funzione.",
-- f2dc99c6 English: Function bindings
[1614] = "Associazioni di funzioni",
-- b19e02e9 English: Alias
[1615] = "Alias",
-- e64bbf11 English: This alias is already in use.
[1616] = "Questo alias è già in uso.",
-- c8037103 English: Function
[1617] = "Funzione",
-- a94fd0ee English: Add binding
[1618] = "Aggiungi associazione",
-- 327c4c8c English: Packaged source is read-only. Duplicate it to create an editable custom
--     function.
[1619] = "Il codice sorgente incluso è in sola lettura. Duplicalo per creare una funzione personalizzata modificabile.",
-- 8299c5ac English: Arguments become Lua parameters. Bindings expose selected helpers under
--     explicit local aliases. Editing an alias does not rewrite your Lua body.
[1620] = "Gli argomenti diventano parametri Lua. Le associazioni espongono le funzioni di supporto selezionate tramite alias locali espliciti. Modificare un alias non riscrive il corpo Lua.",
-- 47b843fc English: New function
[1621] = "Nuova funzione",
-- edb574e3 English: Describe what this function does.
[1622] = "Descrivi cosa fa questa funzione.",
-- 0d646ec9 English: Add a function or duplicate a packaged helper to edit its source.
[1623] = "Aggiungi una funzione o duplica una funzione di supporto inclusa per modificarne il codice sorgente.",
-- aebc00b0 English: LuaWorkbench supplies editing, completion, API knowledge and debugging. Debug
--     runs this buffer explicitly using the test arguments. It does not replace the saved rotation
--     or live callback.
[1624] = "LuaWorkbench fornisce modifica, completamento, conoscenza delle API e debug. Debug esegue esplicitamente questo buffer usando gli argomenti di test. Non sostituisce la rotazione salvata né la callback attiva.",
-- ac6ddfe4 English: Connected: embedded editing, completion, API knowledge and debugging.
[1625] = "Collegato: modifica integrata, completamento, conoscenza delle API e debug.",
-- e3b56b53 English: Review the dependency bundle before applying it.
[1626] = "Esamina il pacchetto di dipendenze prima di applicarlo.",
-- e0ad4daf English: Function bindings (%d)
[1627] = "Associazioni di funzioni (%d)",
-- 1f10215d English: Aliases are local names in your Lua body. Changing an alias does not rewrite
--     the body.
[1628] = "Gli alias sono nomi locali nel tuo corpo Lua. Cambiare un alias non riscrive il corpo.",
-- f81e71de English: Reuse existing
[1629] = "Riusa esistente",
-- c72a3c56 English: Replace existing
[1630] = "Sostituisci esistente",
-- 548fcd9a English: Import with new identifier
[1631] = "Importa con nuovo identificativo",
-- 4759498a English: Create
[1632] = "Crea",
-- 41d342bd English: Review source
[1633] = "Esamina sorgente",
-- 195aae02 English: Original identifier
[1634] = "Identificativo originale",
-- 8bec02bf English: Destination identifier
[1635] = "Identificativo di destinazione",
-- 32e8d276 English: Callback
[1636] = "Callback",
-- 222b67d3 English: Include custom function dependencies
[1637] = "Includi le dipendenze delle funzioni personalizzate",
-- df750ab9 English: Review import
[1638] = "Esamina importazione",
-- 454d876b English: Apply import
[1639] = "Applica importazione",
-- b7143073 English: Function dependency bundle
[1640] = "Pacchetto di dipendenze delle funzioni",
-- 44fc47f3 English: Review the complete bundle before applying an import. Imported Lua can execute
--     when registered; only apply code you trust.
[1641] = "Esamina il pacchetto completo prima di applicare un'importazione. Il Lua importato può essere eseguito al momento della registrazione; applica solo codice di cui ti fidi.",
-- b5ca2246 English: Review each original name, destination and dependency below. Apply import saves
--     the complete reviewed bundle.
[1642] = "Esamina qui sotto ogni nome originale, destinazione e dipendenza. Applica importazione salva l'intero pacchetto esaminato.",
-- 0f2dd42f English: Conflict action
[1643] = "Azione in caso di conflitto",
-- 4e81098c English: Imported name
[1644] = "Nome importato",
-- 8e818b1f English: Existing dependents
[1645] = "Elementi dipendenti esistenti",
-- 75c417a1 English: This imported definition is disabled. Its dependents remain unavailable.
[1646] = "Questa definizione importata è disattivata. Gli elementi che ne dipendono restano non disponibili.",
-- 2643e762 English: Required functions
[1647] = "Funzioni richieste",
-- 103c8bbb English: Paste a bundle above, then review its original names, destinations and required
--     functions.
[1648] = "Incolla un pacchetto qui sopra, poi esamina i nomi originali, le destinazioni e le funzioni richieste.",
-- 7f12e5bc English: Filter Built In or Custom helpers and search their names, identifiers or
--     descriptions. Packaged helpers show read-only source and typed documentation. Duplicate
--     creates an editable copy with a new stable identifier. Argument and return rows document the
--     Lua signature.
[1649] = "Filtra le funzioni di supporto Integrate o Personalizzate e cerca tra nomi, identificativi o descrizioni. Le funzioni di supporto incluse mostrano il codice sorgente in sola lettura e la documentazione tipizzata. Duplica crea una copia modificabile con un nuovo identificativo stabile. Le righe degli argomenti e dei valori restituiti documentano la firma Lua.",
-- 812ccde3 English: Expand Function bindings to add explicit helper aliases and choose their
--     targets. Changing an alias does not rewrite your Lua body. Missing, disabled or invalid
--     dependencies keep their dependents unavailable until repaired.
[1650] = "Espandi Associazioni di funzioni per aggiungere alias espliciti delle funzioni di supporto e sceglierne le destinazioni. Cambiare un alias non riscrive il corpo Lua. Le dipendenze mancanti, disattivate o non valide mantengono non disponibili gli elementi che ne dipendono finché non vengono riparate.",
-- 9d60841e English: Check
[1651] = "Verifica",
-- b64ac05f English: Live
[1652] = "In tempo reale",
-- 324b134f English: Preview
[1653] = "Anteprima",
-- a31ec5d7 English: The preview failed. Use /rm errors for details.
[1654] = "L'anteprima non è riuscita. Usa /rm errors per i dettagli.",
-- 1c103e84 English: Test values were not saved because they are not bounded plain data.
[1655] = "I valori di test non sono stati salvati perché non sono dati semplici e limitati.",
-- c1ab4306 English: Condition check
[1656] = "Verifica della condizione",
-- 0fa00491 English: Fields UI preview
[1657] = "Anteprima interfaccia campi",
-- 367bba74 English: Help preview
[1658] = "Anteprima dell'aiuto",
-- 59e490f3 English: Edit detached test values below. Check validates them before evaluating. Live
--     is opt-in; test values are saved separately from the condition source.
[1659] = "Modifica qui sotto i valori di test separati. Verifica li convalida prima della valutazione. In tempo reale è facoltativo; i valori di test vengono salvati separatamente dal codice sorgente della condizione.",
-- 8b1c0e1c English: Preview runs only this callback with detached sample values. It does not save
--     or register the condition.
[1660] = "L'anteprima esegue solo questa callback con valori di esempio separati. Non salva né registra la condizione.",
-- 75d9602c English: Complete the source fields before checking.
[1661] = "Completa i campi del codice sorgente prima della verifica.",
-- 00454de7 English: Check could not compile the current source. Fix the source before checking
--     again.
[1662] = "Verifica non è riuscita a compilare il codice sorgente attuale. Correggilo prima di verificare di nuovo.",
-- 6a255986 English: Skipped: invalid test values
[1663] = "Saltato: valori di test non validi",
-- 4607aa3d English: Validation: %s
[1664] = "Convalida: %s",
-- 436fe71b English: Passed
[1665] = "Superato",
-- 4c852a7e English: Evaluation: %s
[1666] = "Valutazione: %s",
-- 55a7b6a1 English: Fields UI and Help offer an explicit Preview of the current callback. Preview
--     uses detached sample values and the normal field or help renderer. It does not save,
--     register, validate or evaluate the condition. Closing it releases its controls and returns to
--     the source draft. Check syntax never runs a callback.
[1667] = "Interfaccia campi e Aiuto offrono un'Anteprima esplicita della callback attuale. L'anteprima usa valori di esempio separati e il normale renderer dei campi o dell'aiuto. Non salva, non registra, non convalida e non valuta la condizione. Chiuderla rilascia i suoi controlli e torna alla bozza del codice sorgente. Verifica sintassi non esegue mai una callback.",
-- 106d8f1b English: Evaluate and Validate offer Check with the same Fields UI and detached sample
--     values. Check runs validation first, then evaluates only valid values. Results show true,
--     false or an unavailable reason. Live is opt-in and checks at most twice per second while this
--     panel is shown; closing stops it. Test values are saved separately and never enter condition
--     exports or rotation edits. Source changes run no callbacks unless you check again or enable
--     Live.
[1668] = "Valuta e Convalida offrono Verifica con la stessa Interfaccia campi e valori di esempio separati. Verifica esegue prima la convalida, poi valuta solo i valori validi. I risultati mostrano true, false o un motivo di indisponibilità. In tempo reale è facoltativo e verifica al massimo due volte al secondo mentre questo pannello è visibile; chiuderlo lo interrompe. I valori di test vengono salvati separatamente e non entrano mai nelle esportazioni delle condizioni né nelle modifiche alle rotazioni. Le modifiche al codice sorgente non eseguono callback a meno che tu non verifichi di nuovo o attivi In tempo reale.",
-- 5d331ffe English: Functions reference
[1669] = "Riferimento delle funzioni",
-- 64334745 English: The Functions page documents public helpers and their typed arguments, return
--     values and source. Context completion and hover use that reference; Ctrl-click a known helper
--     to open its source. Use explicit binding aliases for reusable custom helpers.
[1670] = "La pagina Funzioni documenta le funzioni di supporto pubbliche con i loro argomenti tipizzati, valori restituiti e codice sorgente. Il completamento contestuale e i suggerimenti al passaggio del mouse usano questo riferimento; Ctrl-clic su una funzione di supporto nota ne apre il codice sorgente. Usa alias di associazione espliciti per le funzioni di supporto personalizzate riutilizzabili.",
-- 8f344bfe English: The imported definition type does not match this editor.
[1671] = "Il tipo della definizione importata non corrisponde a questo editor.",
-- 91fe2974 English: Test values changed. Check again to refresh the result.
[1672] = "I valori di test sono cambiati. Verifica di nuovo per aggiornare il risultato.",
-- 4087dcf1 English: Complete the highlighted test inputs before checking.
[1673] = "Completa gli input di test evidenziati prima della verifica.",
-- 532eaabd English: Test
[1674] = "Test",
-- e031e0df English: Run test
[1675] = "Esegui test",
-- 312acdf1 English: Test condition
[1676] = "Testa condizione",
-- 34fb96f5 English: Debugger output
[1677] = "Output del debugger",
-- e376955f English: Set test values in Test before debugging Evaluate.
[1678] = "Imposta i valori di test in Test prima di eseguire il debug di Valuta.",
-- 427ea36c English: Debugger output uses a detached sample and the normal field or help container.
[1679] = "L'output del debugger usa un esempio separato e il normale contenitore dei campi o dell'aiuto.",
-- af624aba English: Choose test values in Fields UI, then Run test to validate and evaluate. Help
--     is shown below the fields. Opening Test does not evaluate defaults. Live is opt-in.
[1680] = "Scegli i valori di test in Interfaccia campi, poi Esegui test per convalidare e valutare. L'Aiuto è mostrato sotto i campi. Aprire Test non valuta i valori predefiniti. In tempo reale è facoltativo.",
-- fba588f1 English: Test opens one condition-level dialog from any callback tab. It renders Fields
--     UI and Help together with detached values. Choose the fields and Run test to validate, then
--     evaluate only valid values. Opening the dialog does not evaluate defaults. Live is opt-in and
--     stops when the dialog closes. Committed test values are available to the debugger and stay
--     separate from source, exports and rotation edits. Check syntax never runs a callback.
[1681] = "Test apre un'unica finestra a livello di condizione da qualsiasi scheda di callback. Mostra insieme Interfaccia campi e Aiuto con valori separati. Scegli i campi ed Esegui test per convalidare, poi valutare solo i valori validi. Aprire la finestra non valuta i valori predefiniti. In tempo reale è facoltativo e si interrompe quando la finestra si chiude. I valori di test confermati sono disponibili al debugger e restano separati dal codice sorgente, dalle esportazioni e dalle modifiche alle rotazioni. Verifica sintassi non esegue mai una callback.",
-- deba1c35 English: Nullable
[1682] = "Ammette nil",
-- fbf338e4 English: Add return value
[1683] = "Aggiungi valore restituito",
-- c75ed23e English: Lua returns multiple values in order. Each row documents one result.
[1684] = "Lua restituisce più valori in ordine. Ogni riga documenta un risultato.",
-- f968686c English: Expand code editor
[1685] = "Espandi editor del codice",
-- cc81db61 English: Restore code editor
[1686] = "Ripristina editor del codice",
-- cb050073 English: Choose a source helper and the local name used to call it in this Lua body.
--     Renaming the local name does not rewrite code. Source modules distinguish helpers with the
--     same name.
[1687] = "Scegli una funzione di supporto di origine e il nome locale usato per chiamarla in questo corpo Lua. Rinominare il nome locale non riscrive il codice. I moduli di origine distinguono funzioni di supporto con lo stesso nome.",
-- cfaec007 English: Local name in code
[1688] = "Nome locale nel codice",
-- d076565e English: Source helper
[1689] = "Funzione di supporto di origine",
-- b49f05b5 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. Names suggest the local binding used to call them; registry identifiers stay
--     stable.
[1690] = "I nomi delle funzioni usano lettere, numeri e trattini bassi, e iniziano con una lettera o un trattino basso. I nomi suggeriscono l'associazione locale usata per chiamarle; gli identificativi nel registro restano stabili.",
-- b545dd16 English: This cannot be undone.
[1691] = "Questa operazione non può essere annullata.",
-- f07f87d9 English: Delete this announcement?
[1692] = "Vuoi eliminare questo annuncio?",
-- da985348 English: Type: %s
[1693] = "Tipo: %s",
-- 78a0b485 English: Supported unit-token to localized unit-name lookup. Use value.unit as a key;
--     for example addon.units[value.unit]. Available tokens vary by client.
[1694] = "Tabella supportata da identificativo unità a nome localizzato dell'unità. Usa value.unit come chiave; per esempio addon.units[value.unit]. Gli identificativi disponibili variano in base al client.",
-- b2a921f3 English: Supported unit-token to localized possessive unit-name lookup, such as your
--     target.
[1695] = "Tabella supportata da identificativo unità a nome possessivo localizzato dell'unità, come \"il tuo bersaglio\".",
-- 7e1dc663 English: Rotation Master client compatibility adapter. Its methods return ordinary
--     readable results or nil with a reason when an observation is unavailable. Use a colon call,
--     or pass addon.Platform explicitly as self with a dot reference.
[1696] = "Adattatore di compatibilità del client di Rotation Master. I suoi metodi restituiscono normali risultati leggibili, oppure nil con un motivo quando un'osservazione non è disponibile. Usa una chiamata con i due punti, oppure passa esplicitamente addon.Platform come self con un riferimento col punto.",
-- bbc0cdbf English: Rotation Master spell catalog for resolving client-specific spell IDs, ranks,
--     names, icons and links.
[1697] = "Catalogo degli incantesimi di Rotation Master per risolvere ID, gradi, nomi, icone e link degli incantesimi specifici del client.",
-- 18123a69 English: Utility functions explicitly bound to this condition or function. Choose a
--     completion to bind an available custom function before inserting its reference.
[1698] = "Funzioni di utilità associate esplicitamente a questa condizione o funzione. Scegli un completamento per associare una funzione personalizzata disponibile prima di inserirne il riferimento.",
-- 16356339 English: Rotation Master custom function
[1699] = "Funzione personalizzata di Rotation Master",
-- 902c5c44 English: Rotation Master built-in function
[1700] = "Funzione integrata di Rotation Master",
-- 0443c4a6 English: Rotation Master value
[1701] = "Valore di Rotation Master",
-- 1a845fe0 English: Global function (documentation unavailable on this client)
[1702] = "Funzione globale (documentazione non disponibile su questo client)",
-- 6912e131 English: This client does not provide signature documentation for this function. No
--     arguments or return types have been inferred.
[1703] = "Questo client non fornisce la documentazione della firma per questa funzione. Non sono stati dedotti argomenti né tipi restituiti.",
-- 90092e5f English: Invoke
[1704] = "Invocazione",
-- cb214676 English: Functions are shared across profiles after Apply. Call custom utilities as
--     functions.name(...); accepting completion adds the dependency binding. Typed calls need a
--     binding under Function bindings. Built In examples show dot or colon explicitly.
[1705] = "Le funzioni sono condivise tra i profili dopo Applica. Chiama le utilità personalizzate come functions.name(...); accettare un completamento aggiunge l'associazione della dipendenza. Le chiamate tipizzate richiedono un'associazione in Associazioni di funzioni. Gli esempi integrati mostrano esplicitamente il punto o i due punti.",
-- d03262ba English: Show line numbers
[1706] = "Mostra numeri di riga",
-- f12fff00 English: Line-number visibility applies to every condition and function code editor.
[1707] = "La visibilità dei numeri di riga si applica a ogni editor di codice di condizioni e funzioni.",
-- 596578e6 English: Call a saved custom utility as functions.name(...). Accepting a completion
--     attaches its stable dependency binding; for a typed call, choose its helper under Function
--     bindings. Existing direct aliases still work. The Invoke example shows required addon dot or
--     colon syntax for Built In functions. Renaming an alias does not rewrite source. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1708] = "Chiama un'utilità personalizzata salvata come functions.name(...). Accettare un completamento collega la sua associazione di dipendenza stabile; per una chiamata tipizzata, scegli la sua funzione di supporto in Associazioni di funzioni. Gli alias diretti esistenti funzionano ancora. L'esempio di Invocazione mostra la sintassi addon con punto o due punti richiesta per le funzioni integrate. Rinominare un alias non riscrive il codice sorgente. Le dipendenze mancanti, disattivate o non valide rendono non disponibili gli elementi che le usano.",
-- 38416c88 English: Choose the editor for custom Lua conditions and functions. Show line numbers
--     applies across code editors. Built In syntax highlighting and Plain text work without another
--     addon. Automatic selects a connected provider or falls back safely. Apply saves settings;
--     editor changes take effect on reopening, and line-number visibility updates open editors.
--     LuaWorkbench and WowLua loading status is shown separately from integration availability.
[1709] = "Scegli l'editor per le condizioni e le funzioni Lua personalizzate. Mostra numeri di riga si applica a tutti gli editor di codice. Evidenziazione della sintassi integrata e Testo semplice funzionano senza altri addon. Automatico seleziona un fornitore collegato o ripiega in modo sicuro. Applica salva le impostazioni; i cambi di editor hanno effetto alla riapertura, mentre la visibilità dei numeri di riga aggiorna gli editor aperti. Lo stato di caricamento di LuaWorkbench e WowLua è mostrato separatamente dalla disponibilità dell'integrazione.",
-- 50c3cb6e English: All namespaces
[1710] = "Tutti gli spazi dei nomi",
-- 5605815a English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self: the Invoke example includes a method receiver explicitly, and
--     Existing API preserves its original dot or colon spelling. Existing aliases still work.
--     Renaming a function or namespace does not rewrite existing code or bindings. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1711] = "Chiama un'utilità come namespace.name(...). Gli spazi dei nomi integrati seguono i file sorgente; le funzioni personalizzate scelgono il proprio Spazio dei nomi. Accettare un completamento collega la sua associazione di dipendenza stabile; per una chiamata tipizzata, aggiungi il suo nome qualificato in Associazioni di funzioni. Gli spazi dei nomi non forniscono self: l'esempio di Invocazione include esplicitamente il ricevitore del metodo, e API esistente conserva la sua scrittura originale con punto o due punti. Gli alias esistenti funzionano ancora. Rinominare una funzione o uno spazio dei nomi non riscrive il codice né le associazioni esistenti. Le dipendenze mancanti, disattivate o non valide rendono non disponibili gli elementi che le usano.",
-- 66506282 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. Namespaces are private to this callback. Renaming a binding does not rewrite
--     code.
[1712] = "Scegli una funzione di supporto di origine e il suo nome in questo corpo Lua, come custom.ready o utils.getCached. Gli spazi dei nomi sono privati di questa callback. Rinominare un'associazione non riscrive il codice.",
-- 5226404c English: Existing API
[1713] = "API esistente",
-- e572edc2 English: Name in code
[1714] = "Nome nel codice",
-- c4e4e7ab English: Namespace
[1715] = "Spazio dei nomi",
-- c6d86222 English: Namespaces group functions; they do not supply a receiver. Accept a completion
--     to bind the shown dotted call. For a typed call, add the same qualified name under Function
--     bindings. Method examples include the required receiver explicitly. Functions are shared
--     across profiles after Apply.
[1716] = "Gli spazi dei nomi raggruppano le funzioni; non forniscono un ricevitore. Accetta un completamento per associare la chiamata con punto mostrata. Per una chiamata tipizzata, aggiungi lo stesso nome qualificato in Associazioni di funzioni. Gli esempi di metodi includono esplicitamente il ricevitore richiesto. Le funzioni sono condivise tra i profili dopo Applica.",
-- 76209725 English: Private utility-function namespace. It contains only explicit bindings for this
--     callback.
[1717] = "Spazio dei nomi privato delle funzioni di utilità. Contiene solo le associazioni esplicite per questa callback.",
-- 481da3a7 English: Argument
[1718] = "Argomento",
-- e0836fce English: Bindings (%d)
[1719] = "Associazioni (%d)",
-- 6ecb5a70 English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is Lua shorthand for object.method(object, x). Existing addon APIs remain
--     compatible with saved definitions. Existing aliases still work. Renaming a function or
--     namespace does not rewrite existing code or bindings. Missing, disabled or invalid
--     dependencies keep consumers unavailable.
[1720] = "Chiama un'utilità come namespace.name(...). Gli spazi dei nomi integrati seguono i file sorgente; le funzioni personalizzate scelgono il proprio Spazio dei nomi. Accettare un completamento collega la sua associazione di dipendenza stabile; per una chiamata tipizzata, aggiungi il suo nome qualificato in Associazioni di funzioni. Gli spazi dei nomi non forniscono self. In una chiamata con punto qualificata da uno spazio dei nomi, passa esplicitamente il ricevitore del metodo; object:method(x) è la forma abbreviata Lua di object.method(object, x). Le API esistenti dell'addon restano compatibili con le definizioni salvate. Gli alias esistenti funzionano ancora. Rinominare una funzione o uno spazio dei nomi non riscrive il codice né le associazioni esistenti. Le dipendenze mancanti, disattivate o non valide rendono non disponibili gli elementi che le usano.",
-- d35a9985 English: Changing argument or return order can break existing callers. Rotation Master
--     will not rewrite their Lua code. Continue?
[1721] = "Cambiare l'ordine degli argomenti o dei valori restituiti può compromettere i chiamanti esistenti. Rotation Master non riscriverà il loro codice Lua. Vuoi continuare?",
-- 2199cecc English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Reordering a saved function warns because positional callers may
--     need changes; RM does not rewrite call sites.
[1722] = "Clicca sull'intestazione Argomenti o Valori restituiti per comprimerla o espanderla. + Argomento e + Valore restituito aggiungono in fondo se cliccati, o inseriscono in uno spazio evidenziato se trascinati. Trascina una riga o usa Su / Giù per riordinare; Ctrl-trascinamento porta con sé le righe successive. Il cestino rimuove una riga. Tipo e Ammette nil documentano i valori accettati; Descrizione spiega ogni input o risultato. Lua può restituire più risultati ordinati. Riordinare una funzione salvata mostra un avviso perché i chiamanti posizionali possono richiedere modifiche; RM non riscrive i punti di chiamata.",
-- 6b0143d0 English: Return
[1723] = "Valore restituito",
-- 2584fdfb English: Changing argument order can break existing callers. Rotation Master will not
--     rewrite their Lua code. Continue?
[1724] = "Cambiare l'ordine degli argomenti può compromettere i chiamanti esistenti. Rotation Master non riscriverà il loro codice Lua. Vuoi continuare?",
-- 79fbb27b English: Changing return documentation order does not rewrite return statements or
--     existing callers. Review the Lua body and callers for the new order. Continue?
[1725] = "Cambiare l'ordine della documentazione dei valori restituiti non riscrive le istruzioni return né i chiamanti esistenti. Controlla che il corpo Lua e i chiamanti rispettino il nuovo ordine. Vuoi continuare?",
-- 2266dd0b English: Card controls
[1726] = "Controlli della scheda",
-- 1f03f52f English: Describe this value for function documentation, completion and hover help.
--     Changes remain in the draft until Apply.
[1727] = "Descrivi questo valore per la documentazione della funzione, il completamento automatico e l'aiuto al passaggio del mouse. Le modifiche restano nella bozza fino ad Applica.",
-- 9513dcfb English: Drag a card to reorder arguments; Ctrl-drag includes following arguments. Up
--     and down move one position. Duplicate copies the argument with a unique name; the trash can
--     removes it. Reordering a saved function requires confirmation because existing callers are
--     not rewritten.
[1728] = "Trascina una scheda per riordinare gli argomenti; Ctrl+trascinamento include anche gli argomenti successivi. Su e Giù spostano di una posizione. Duplica copia l'argomento con un nome univoco; il cestino lo rimuove. Riordinare una funzione salvata richiede una conferma, perché i chiamanti esistenti non vengono riscritti.",
-- 33f24b5d English: Drag a card to reorder return documentation; Ctrl-drag includes following
--     returns. Up and down move one position. Duplicate copies the documented return value; the
--     trash can removes it. Return order in this list does not rewrite return statements or
--     callers.
[1729] = "Trascina una scheda per riordinare la documentazione dei valori restituiti; Ctrl+trascinamento include anche quelli successivi. Su e Giù spostano di una posizione. Duplica copia il valore restituito documentato; il cestino lo rimuove. L'ordine in questo elenco non riscrive le istruzioni return né i chiamanti.",
-- 74057930 English: Rendered output appears here when the callback runs or steps through widget
--     creation.
[1730] = "L'output generato compare qui quando la callback viene eseguita o quando procedi passo passo nella creazione dei widget.",
-- 47b50257 English: Set values in Test before running or debugging this condition.
[1731] = "Imposta i valori in Test prima di eseguire questa condizione o di farne il debug.",
-- 96aa8cc3 English: The argument name is the local parameter available in the Lua body. Use a valid
--     Lua identifier. Renaming this documentation does not rewrite references in the code.
[1732] = "Il nome dell'argomento è il parametro locale disponibile nel corpo Lua. Usa un identificatore Lua valido. Rinominarlo nella documentazione non riscrive i riferimenti nel codice.",
-- 438e9a47 English: Type and Nullable describe the values accepted or returned by this function.
--     They document the contract; they do not rewrite or validate values in the Lua body.
[1733] = "Tipo e Nullable descrivono i valori accettati o restituiti da questa funzione. Documentano il contratto; non riscrivono né convalidano i valori nel corpo Lua.",
-- 42e8bcf1 English: Debuffs
[1734] = "Penalità",
-- e89b30aa English: Resources
[1735] = "Risorse",
-- 8f0d1b30 English: Pet
[1736] = "Famiglio",
-- 7c400199 English: Logic
[1737] = "Logica",
-- 9e471951 English: Environment
[1738] = "Ambiente",
-- 33b93476 English: Time
[1739] = "Tempo",
-- 66f9cfa2 English: Spell Auto-Repeat Active
[1740] = "Ripetizione automatica dell'incantesimo attiva",
-- 35f743e1 English: Retribution (Wowhead & wowsims)
[1741] = "Castigo (Wowhead & wowsims)",
-- 6fc82107 English: Melee Retribution from level 1 to 70, and the default for any Paladin no other
--     premade fits. Opens each target with Judgement of Wisdom (low mana) or the Crusader, keeps
--     your best seal up (Blood or Martyr, Command, then Righteousness), Crusader Strike, judges
--     only Righteousness, Blood or Martyr (or Command on a stunned target), Exorcism on Undead and
--     Demons, Consecration for three or more enemies with mana to spare. Hammer of Wrath is left to
--     you (Wowhead uses it only on fleeing targets). Reminders: Sanctity, Retribution or Devotion
--     Aura, a Blessing on yourself, a heal after the fight, Avenging Wrath. Seal twisting is a
--     separate premade.
[1742] = "Castigo in mischia dal livello 1 al 70, e la scelta predefinita per qualsiasi Paladino a cui non si adatta nessun'altra rotazione integrata. Apre ogni bersaglio con Giudizio della Saggezza (mana basso) o del Crociato, mantiene attivo il tuo sigillo migliore (Sangue o Martire, Comando, poi Rettitudine), Assalto del Crociato, giudica solo Rettitudine, Sangue o Martire (o Comando su un bersaglio stordito), Esorcismo su Non Morti e Demoni, Consacrazione contro tre o più nemici se il mana lo consente. Martello dell'Ira è lasciato a te (Wowhead lo usa solo sui bersagli in fuga). Promemoria: Aura della Santità, del Castigo o della Devozione, una Benedizione su di te, una cura dopo il combattimento, Ira Vendicatrice. L'alternanza dei sigilli è una rotazione integrata separata.",
-- 89f00a09 English: Retribution (Icy Veins)
[1743] = "Castigo (Icy Veins)",
-- c68e9ea0 English: Icy Veins' Retribution, an alternative to the recommended Wowhead Retribution
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader once per target, Seal of Righteousness (Command only with a slow weapon, Blood
--     or Martyr once learned), Crusader Strike, Hammer of Wrath and Judgement on cooldown,
--     Consecration on two or more enemies, Exorcism on Undead and Demons, and Holy Shock for Holy
--     levelers. Same reminders as the Wowhead variant.
[1744] = "Il Castigo di Icy Veins, un'alternativa alla rotazione integrata consigliata Castigo di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Giudizio del Crociato una volta per bersaglio, Sigillo della Rettitudine (Comando solo con un'arma lenta, Sangue o Martire una volta appresi), Assalto del Crociato, Martello dell'Ira e Giudizio appena pronti, Consacrazione contro due o più nemici, Esorcismo su Non Morti e Demoni, e Folgore Sacra per chi livella come Sacro. Stessi promemoria della variante Wowhead.",
-- 85d846bd English: Retribution seal twisting
[1745] = "Castigo con alternanza dei sigilli",
-- 34a6a34f English: Off by default; enable it if you twist seals (level 64+, Seal of Command and
--     Blood or Martyr). Opens with Judgement of the Crusader, then each swing puts up Seal of
--     Command (rank 1) early and switches to Blood or Martyr in the last 0.4 seconds, Crusader
--     Strike between twists, judges only Blood or Martyr, Exorcism and Consecration only as
--     fillers, and rolls Blood without twisting below 12% mana. Needs a reliable swing timer;
--     latency is not accounted for.
[1746] = "Disattivata per impostazione predefinita; attivala se alterni i sigilli (livello 64+, Sigillo del Comando e Sangue o Martire). Apre con Giudizio del Crociato, poi a ogni colpo mette presto Sigillo del Comando (grado 1) e passa a Sangue o Martire negli ultimi 0,4 secondi, Assalto del Crociato tra un'alternanza e l'altra, giudica solo Sangue o Martire, Esorcismo e Consacrazione solo come riempitivi, e sotto il 12% di mana mantiene Sangue senza alternare. Richiede un timer degli attacchi affidabile; la latenza non viene considerata.",
-- 316a63c1 English: Protection (Wowhead & wowsims)
[1747] = "Protezione (Wowhead & wowsims)",
-- c9c2efbf English: Tanking for the Protection tree or any Paladin with Righteous Fury on. Pulls
--     with Holy Shield, Avenger's Shield and Judgement; against a crushing target (world boss or
--     three or more levels above you) Holy Shield comes first; then Consecration, Exorcism on
--     Undead and Demons, Judgement, Holy Shield, Holy Wrath on undead packs, Avenger's Shield
--     except on crushing targets. Seal of Wisdom on packs when mana is short, Righteousness
--     otherwise. Reminders: Righteous Fury, Devotion Aura, Sanctuary (or Kings, or Wisdom),
--     Avenging Wrath, Lay on Hands. Taunts and target swaps stay with you.
[1748] = "Ruolo da difensore per l'albero Protezione o per qualsiasi Paladino con Giusta Furia attiva. Ingaggia con Scudo Sacro, Scudo del Vendicatore e Giudizio; contro un bersaglio con colpi schiaccianti (boss mondiale o di tre o più livelli sopra di te) Scudo Sacro viene per primo; poi Consacrazione, Esorcismo su Non Morti e Demoni, Giudizio, Scudo Sacro, Biasimo sui gruppi di non morti, Scudo del Vendicatore tranne sui bersagli con colpi schiaccianti. Sigillo della Saggezza sui gruppi quando il mana è scarso, altrimenti Rettitudine. Promemoria: Giusta Furia, Aura della Devozione, Santuario (o Re, o Saggezza), Ira Vendicatrice, Mano Celestiale. Provocazioni e cambi di bersaglio restano a te.",
-- 80b938a1 English: Protection (Icy Veins)
[1749] = "Protezione (Icy Veins)",
-- 3ae9045e English: Icy Veins' tanking, an alternative to the recommended Wowhead Protection
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader when nobody keeps it up, Righteousness (Wisdom on packs), Consecration as the
--     main threat, Judgement, Holy Shield, then Avenger's Shield and Hammer of Wrath on cooldown.
--     Same reminders as the Wowhead variant without Avenging Wrath.
[1750] = "Il ruolo da difensore di Icy Veins, un'alternativa alla rotazione integrata consigliata Protezione di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Giudizio del Crociato quando nessuno lo mantiene, Rettitudine (Saggezza sui gruppi), Consacrazione come principale fonte di minaccia, Giudizio, Scudo Sacro, poi Scudo del Vendicatore e Martello dell'Ira appena pronti. Stessi promemoria della variante Wowhead, senza Ira Vendicatrice.",
-- 9d88b75a English: Holy (Icy Veins & Wowhead)
[1751] = "Sacro (Icy Veins & Wowhead)",
-- 879586c5 English: Healing for a Holy Paladin in a group, on your friendly target: Lay on Hands or
--     Holy Shock for a dying target, Cleanse (Purify before 42), Holy Shock while moving, Holy
--     Light for heavy damage, rank-5 Holy Light to keep Light's Grace up, Flash of Light otherwise.
--     With a hostile target it keeps Judgement of Wisdom up. Reminders: Concentration Aura,
--     Blessing of Wisdom, Divine Illumination and Divine Favor. A soloing Holy Paladin gets a
--     Retribution premade instead.
[1752] = "Cure per un Paladino Sacro in gruppo, sul tuo bersaglio amico: Mano Celestiale o Folgore Sacra per un bersaglio in punto di morte, Purificazione (Purifica prima del 42), Folgore Sacra in movimento, Luce Sacra per danni pesanti, Luce Sacra di grado 5 per mantenere Grazia della Luce, altrimenti Lampo di Luce. Con un bersaglio ostile mantiene attivo Giudizio della Saggezza. Promemoria: Aura della Concentrazione, Benedizione della Saggezza, Illuminazione Divina e Favore Divino. Un Paladino Sacro che gioca da solo riceve invece una rotazione integrata Castigo.",
-- 2261d994 English: Holy (Wowhead tank healing)
[1753] = "Sacro (cure sul difensore, Wowhead)",
-- 63b194ff English: Wowhead's raid tank healing, an alternative to the recommended Holy premade,
--     off by default: enable it and disable that one, or raise its priority. Holy Light whenever
--     your target is missing a tenth of their health, Flash of Light only for small deficits, with
--     the same emergencies, cleansing, Judgement and reminders as the blended Holy premade.
[1754] = "Le cure sul difensore in incursione di Wowhead, un'alternativa alla rotazione integrata consigliata Sacro, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Luce Sacra ogni volta che al tuo bersaglio manca un decimo della salute, Lampo di Luce solo per piccole carenze, con le stesse emergenze, purificazioni, Giudizio e promemoria della rotazione integrata Sacro combinata.",
-- 4396ff42 English: Ranged DPS (wowsims)
[1755] = "DPS a distanza (wowsims)",
-- 2b43c4a1 English: Levels 1–70, every spec. Pulls with Hunter's Mark, Aimed Shot and Auto Shot,
--     keeps Auto Shot running and uses melee strikes when a target reaches you. Before Steady Shot
--     it keeps your Serpent Sting up and spends mana on Aimed, Multi and Arcane Shot only while you
--     have plenty. From level 62: Multi-Shot when ready, Steady Shot straight after each Auto Shot,
--     Arcane Shot to fill the gap, Serpent Sting when solo. With three or more enemies fighting
--     you, Multi-Shot whenever it is ready. Reminds you of aspects (Viper when mana runs low, Hawk
--     again at half mana), pet care, Kill Command, major cooldowns on elites and bosses and
--     Silencing Shot. Pet commands, Misdirection, traps, Volley, melee weaving and Feign Death stay
--     with you.
[1756] = "Livelli 1–70, ogni specializzazione. Ingaggia con Marchio del Cacciatore, Tiro Mirato e Tiro Automatico, mantiene attivo il Tiro Automatico e usa gli attacchi in mischia quando un bersaglio ti raggiunge. Prima di Tiro Fermo mantiene il tuo Morso della Serpe e spende mana in Tiro Mirato, Tiro Multiplo e Tiro Arcano solo finché ne hai in abbondanza. Dal livello 62: Tiro Multiplo appena pronto, Tiro Fermo subito dopo ogni Tiro Automatico, Tiro Arcano per riempire i vuoti, Morso della Serpe quando giochi da solo. Con tre o più nemici che ti combattono, Tiro Multiplo ogni volta che è pronto. Ti ricorda gli aspetti (Vipera quando il mana scarseggia, di nuovo Falco a metà mana), la cura del famiglio, Ordine di Morte, i principali tempi di recupero su élite e boss e Tiro Silenziante. Comandi del famiglio, Depistaggio, trappole, Raffica, alternanza con la mischia e Morte Apparente restano a te.",
-- 825c84d1 English: Ranged DPS (Wowhead)
[1757] = "DPS a distanza (Wowhead)",
-- fb9ad1ee English: Levels 1–70, every spec, following Wowhead's raid advice. Same pull, melee,
--     leveling shots, multi-target Multi-Shot and reminders as the wowsims version, but once Steady
--     Shot is learned it only offers Multi-Shot and Steady Shot after each Auto Shot: no Arcane
--     Shot filler (except while moving), no Serpent Sting and no Aspect of the Viper reminder. Pet
--     commands, Misdirection, traps, Volley, melee weaving and Feign Death stay with you. An
--     alternative to the recommended wowsims ranged premade, off by default: enable it and disable
--     that one, or raise its priority.
[1758] = "Livelli 1–70, ogni specializzazione, seguendo i consigli di Wowhead per le incursioni. Stesso ingaggio, mischia, tiri da livellamento, Tiro Multiplo contro più bersagli e promemoria della versione wowsims, ma una volta appreso Tiro Fermo propone solo Tiro Multiplo e Tiro Fermo dopo ogni Tiro Automatico: niente Tiro Arcano come riempitivo (tranne in movimento), niente Morso della Serpe e niente promemoria di Aspetto della Vipera. Comandi del famiglio, Depistaggio, trappole, Raffica, alternanza con la mischia e Morte Apparente restano a te. Un'alternativa alla rotazione integrata consigliata a distanza di wowsims, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- 469b61e4 English: Melee DPS (wowsims)
[1759] = "DPS in mischia (wowsims)",
-- a600e4ad English: Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or
--     Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte,
--     Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a
--     target about to die, and at five points Rupture when it will last (not while Blade Flurry
--     cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is
--     not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons,
--     Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot,
--     Feint, Vanish and positioning stay with you.
[1760] = "Livelli 1–70, ogni specializzazione. Dalla furtività: Premeditazione, poi Colpo Basso da solo o Garrota in gruppo, altrimenti Imboscata (con un pugnale nella mano principale). In combattimento: Risposta, Fendenti Furiosi da due punti combo (rinnovato negli ultimi due secondi), Eliminazione su un bersaglio in punto di morte, e a cinque punti Perforazione quando durerà (non mentre Vortice di Lame colpisce più bersagli), altrimenti Eliminazione. Accumula punti con Mutilazione o Pugnalata alle Spalle (pugnale) quando il bersaglio non ti attacca, altrimenti con Emorragia o Assalto Funesto. Ti ricorda i veleni mancanti, Calcio, Vortice di Lame e Scarica d'Adrenalina, Sangue Freddo ed Evasione. Esponi Armatura, Colpo ai Reni, Finta, Sparizione e il posizionamento restano a te.",
-- 5f9b3940 English: Melee DPS (Wowhead)
[1761] = "DPS in mischia (Wowhead)",
-- 19e52877 English: Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and
--     reminders as the wowsims version, but Slice and Dice starts from one combo point and every
--     five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and
--     positioning stay with you. An alternative to the recommended wowsims melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority.
[1762] = "Livelli 1–70, ogni specializzazione, seguendo Wowhead. Stesse aperture dalla furtività, generatori di punti e promemoria della versione wowsims, ma Fendenti Furiosi parte da un punto combo e ogni mossa finale a cinque punti è Eliminazione: niente Perforazione. Esponi Armatura, Colpo ai Reni, Finta, Sparizione e il posizionamento restano a te. Un'alternativa alla rotazione integrata consigliata DPS in mischia di wowsims, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- d05e07b7 English: Balance
[1763] = "Equilibrio",
-- 8177cc43 English: Caster Balance from level 1 to 70, and the default for any Druid no other
--     premade fits. Pulls with Starfire (Wrath before 20), Insect Swarm and Moonfire while moving,
--     Faerie Fire in a group, Hurricane for three or more enemies, Moonfire when it has run out and
--     you have 30% mana, Starfire on Nature's Grace, Wrath against a target in melee, then Starfire
--     (Wrath before it is learned). No advice in Cat, Bear or travel forms. Reminders: Mark of the
--     Wild, Thorns while solo, Omen of Clarity, Moonkin Form, Force of Nature on a long fight,
--     Innervate when low.
[1764] = "Equilibrio a distanza dal livello 1 al 70, e la scelta predefinita per qualsiasi Druido a cui non si adatta nessun'altra rotazione integrata. Ingaggia con Fuoco Stellare (Ira Silvana prima del 20), Sciame d'Insetti e Fuoco Lunare in movimento, Fuoco Fatato in gruppo, Uragano contro tre o più nemici, Fuoco Lunare quando è scaduto e hai il 30% di mana, Fuoco Stellare con Grazia della Natura, Ira Silvana contro un bersaglio in mischia, poi Fuoco Stellare (Ira Silvana prima di averlo appreso). Nessun consiglio in Forma Felina, Forma d'Orso o forme di viaggio. Promemoria: Marchio Selvaggio, Spine quando giochi da solo, Presagio di Lucidità, Forma di Lunagufo, Forza della Natura in un combattimento lungo, Innervazione quando il mana è basso.",
-- 9a2fa639 English: Feral (Icy Veins, Warcraft Tavern & wowsims)
[1765] = "Combattimento Ferino (Icy Veins, Warcraft Tavern & wowsims)",
-- 43a0ca32 English: Cat and bear for the Feral tree, following your form. Cat: stealth opener
--     (Pounce, Ravage or Shred), Faerie Fire (Feral), Rip at four combo points on a target that
--     lives, Ferocious Bite between Rips without Clearcasting, Mangle kept up, Shred from behind or
--     Mangle/Claw when the target is on you. Bear: Faerie Fire, Lacerate saved before it drops,
--     Demoralizing Roar unless a warrior's Shout is up, Swipe for packs, Mangle, five Lacerates,
--     Swipe. In caster form it suggests Cat (or Bear) Form. Reminders: Mark, Thorns, Omen, Maul
--     with spare rage, Tiger's Fury before a pull, Frenzied Regeneration. Powershifting is an
--     optional step that starts off (it needs a powershift macro).
[1766] = "Felino e orso per l'albero Combattimento Ferino, in base alla tua forma. Felino: apertura dalla furtività (Balzo, Devastazione o Artigliata), Fuoco Fatato (Ferino), Squarcio a quattro punti combo su un bersaglio che sopravvivrà, Morso Feroce tra uno Squarcio e l'altro senza Lucidità, Maciullamento sempre attivo, Artigliata da dietro oppure Maciullamento/Artiglio quando il bersaglio ti attacca. Orso: Fuoco Fatato, Lacerazione rinnovata prima che scada, Ruggito Inabilitante a meno che non sia attivo l'Urlo di un guerriero, Spazzata contro i gruppi, Maciullamento, cinque Lacerazioni, Spazzata. In forma umanoide suggerisce Forma Felina (o Forma d'Orso). Promemoria: Marchio, Spine, Presagio, Zampata con l'ira in eccesso, Furia della Tigre prima di un ingaggio, Rigenerazione Furiosa. Il powershifting è un passaggio facoltativo, disattivato all'inizio (richiede una macro di powershift).",
-- 4c55a525 English: Feral (Wowhead)
[1767] = "Combattimento Ferino (Wowhead)",
-- 9092413a English: Wowhead's Feral, an alternative to the recommended Icy Veins Feral premade, off
--     by default: enable it and disable that one, or raise its priority. Rip whenever it is down at
--     four combo points and Ferocious Bite only on a target about to die (no bite-weaving); bears
--     spend free global cooldowns on Lacerate before Swipe. Innervate when a cat runs low on mana.
--     Otherwise the same as the Icy Veins variant.
[1768] = "Il Combattimento Ferino di Wowhead, un'alternativa alla rotazione integrata consigliata Combattimento Ferino di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Squarcio ogni volta che manca a quattro punti combo e Morso Feroce solo su un bersaglio in punto di morte (niente alternanza con il morso); gli orsi spendono i tempi di recupero globali liberi in Lacerazione prima di Spazzata. Innervazione quando un felino resta a corto di mana. Per il resto è uguale alla variante Icy Veins.",
-- 6a3c6c77 English: Restoration
[1769] = "Rigenerazione",
-- da5557c1 English: Healing for the Restoration tree on your friendly target (or yourself): Healing
--     Touch after Nature's Swiftness, Swiftmend a dying target that has your Rejuvenation or
--     Regrowth, three rolling Lifeblooms in combat, Rejuvenation and Regrowth when missing, then
--     Regrowth in Tree of Life or Healing Touch outside it. A hostile target gets Moonfire and
--     Wrath for soloing. Reminders: Mark, Omen, Tree of Life, Nature's Swiftness, Tranquility,
--     Innervate and Rebirth. Choosing whom to heal and downranking stay with you.
[1770] = "Cure per l'albero Rigenerazione sul tuo bersaglio amico (o su di te): Tocco di Guarigione dopo Rapidità della Natura, Guarigione Immediata su un bersaglio in punto di morte con il tuo Rinvigorimento o la tua Ricrescita, tre Boccioli di Vita mantenuti in combattimento, Rinvigorimento e Ricrescita quando mancano, poi Ricrescita in forma di Albero della Vita o Tocco di Guarigione fuori da essa. Un bersaglio ostile riceve Fuoco Lunare e Ira Silvana per giocare da solo. Promemoria: Marchio, Presagio, Albero della Vita, Rapidità della Natura, Tranquillità, Innervazione e Pronto Ritorno. La scelta di chi curare e l'uso dei gradi inferiori restano a te.",
-- 469b61e4 English: Melee DPS (wowsims)
[1771] = "DPS in mischia (wowsims)",
-- e30bf8c3 English: Levels 1–70, Arms or Fury. Charges to pull, then Victory Rush, Intercept,
--     Rampage, and Whirlwind when two or more enemies fight you (Thunder Clap before it is
--     learned). With Bloodthirst or Mortal Strike: that strike, Whirlwind with rage to spare,
--     Execute, Overpower. Before them: Whirlwind, Execute, Overpower, Rend. Spare rage goes to
--     Devastate or Sunder Armor, then Hamstring. Reminds you of Battle Shout, Bloodrage, Heroic
--     Strike or Cleave as rage dumps, Sweeping Strikes, Death Wish, Recklessness and interrupts.
--     Slam timing, stance dancing and Berserker Rage stay with you.
[1772] = "Livelli 1–70, Armi o Furia. Carica per ingaggiare, poi Frenesia di Vittoria, Intercettazione, Scatenamento e Turbine quando due o più nemici ti combattono (Schianto del Tuono prima di averlo appreso). Con Sete di Sangue o Assalto Mortale: quel colpo, Turbine con ira in eccesso, Esecuzione, Dominazione. Prima di averli: Turbine, Esecuzione, Dominazione, Squartamento. L'ira in eccesso va in Sfondamento o Spaccarmatura, poi Azzoppamento. Ti ricorda Urlo di Battaglia, Ira Sanguinaria, Assalto Eroico o Fendente per smaltire l'ira, Colpi Ampi, Desiderio di Morte, Avventatezza e le interruzioni. Il tempismo di Contusione, il cambio di postura e Furia del Berserker restano a te.",
-- 6d10d944 English: Melee DPS (Icy Veins)
[1773] = "DPS in mischia (Icy Veins)",
-- c50ff4f3 English: Levels 1–70, Arms or Fury, following Icy Veins. Same pull, reminders and
--     leveling steps as the wowsims version, but with Mortal Strike Execute comes first, with
--     Bloodthirst Execute comes right after it, Whirlwind follows without holding rage, and
--     Hamstring only near full rage. Slam timing, stance dancing and Berserker Rage stay with you.
--     An alternative to the recommended wowsims melee DPS premade, off by default: enable it and
--     disable that one, or raise its priority.
[1774] = "Livelli 1–70, Armi o Furia, seguendo Icy Veins. Stesso ingaggio, promemoria e passaggi di livellamento della versione wowsims, ma con Assalto Mortale Esecuzione viene per prima, con Sete di Sangue Esecuzione viene subito dopo, Turbine segue senza trattenere l'ira e Azzoppamento solo con l'ira quasi piena. Il tempismo di Contusione, il cambio di postura e Furia del Berserker restano a te. Un'alternativa alla rotazione integrata consigliata DPS in mischia di wowsims, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- 871d5911 English: Tank (Wowhead)
[1775] = "Difensore (Wowhead)",
-- 91dfa1ce English: Levels 10–70, chosen while you are in Defensive Stance. Shield Slam, Revenge,
--     Thunder Clap and Demoralizing Shout kept up on elites and bosses, then Devastate or Sunder
--     Armor. On packs: Thunder Clap and Demoralizing Shout first. Reminds you of Shield Block (with
--     a shield equipped) against bosses and higher-level enemies, Heroic Strike or Cleave, Battle
--     Shout, Bloodrage, Shield Bash and emergency Last Stand and Shield Wall. Taunting and other
--     utility stay with you.
[1776] = "Livelli 10–70, scelta mentre sei in Postura Difensiva. Colpo di Scudo, Rivincita, Schianto del Tuono e Urlo Demoralizzante mantenuti su élite e boss, poi Sfondamento o Spaccarmatura. Contro i gruppi: prima Schianto del Tuono e Urlo Demoralizzante. Ti ricorda Scudo Saldo (con uno scudo equipaggiato) contro i boss e i nemici di livello superiore, Assalto Eroico o Fendente, Urlo di Battaglia, Ira Sanguinaria, Botta di Scudo e, in emergenza, Ultima Difesa e Muro di Scudi. Provocazioni e altre utilità restano a te.",
-- ea76d926 English: Tank (Icy Veins)
[1777] = "Difensore (Icy Veins)",
-- aa141592 English: Levels 10–70, chosen while you are in Defensive Stance, following Icy Veins.
--     Shield Slam, Revenge, then Devastate or Sunder Armor, with Rend at the start of a fight until
--     Shield Slam is learned. On packs: Thunder Clap, and Demoralizing Shout against elites. Shield
--     Block is reminded whenever your target is attacking you and you carry a shield. Taunting and
--     other utility stay with you. An alternative to the recommended Wowhead tank premade, off by
--     default: enable it and disable that one, or raise its priority.
[1778] = "Livelli 10–70, scelta mentre sei in Postura Difensiva, seguendo Icy Veins. Colpo di Scudo, Rivincita, poi Sfondamento o Spaccarmatura, con Squartamento all'inizio del combattimento finché non hai appreso Colpo di Scudo. Contro i gruppi: Schianto del Tuono, e Urlo Demoralizzante contro le élite. Scudo Saldo viene ricordato ogni volta che il tuo bersaglio ti attacca e porti uno scudo. Provocazioni e altre utilità restano a te. Un'alternativa alla rotazione integrata consigliata da difensore di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- 3adec7ba English: Damage (Icy Veins)
[1779] = "Danni (Icy Veins)",
-- 9b0711bb English: Damage from level 1 to 70, used whenever the healer premade does not apply.
--     Smite and wand early, then Mind Blast, Shadow Word: Pain, Mind Flay, Shadowform, Vampiric
--     Touch and Shadow Word: Death as you learn them; DoTs before Mind Blast; a dying target is
--     wanded when solo. Holy and Discipline questers get Holy Fire and Smite. Reminders: Inner
--     Fire, Fortitude, racial buffs, Inner Focus, Shadowfiend. A Mind Flay past its first tick is
--     cut short for a ready Mind Blast, or Shadow Word: Death above half health. Shields and
--     healing stay with you.
[1780] = "Danni dal livello 1 al 70, usata ogni volta che la rotazione integrata da guaritore non si applica. All'inizio Punizione e bacchetta, poi Detonazione Mentale, Parola d'Ombra: Dolore, Flagello Mentale, Forma d'Ombra, Tocco Vampirico e Parola d'Ombra: Morte man mano che li apprendi; i danni periodici prima di Detonazione Mentale; da solo, un bersaglio in punto di morte viene finito con la bacchetta. Chi completa missioni come Sacro o Disciplina riceve Fuoco Sacro e Punizione. Promemoria: Fuoco Interiore, Fermezza, effetti benefici razziali, Concentrazione Interiore, Spirito d'Ombra. Un Flagello Mentale oltre il primo impulso viene interrotto per una Detonazione Mentale pronta, o per Parola d'Ombra: Morte sopra metà salute. Scudi e cure restano a te.",
-- ce79d246 English: Damage (Wowhead)
[1781] = "Danni (Wowhead)",
-- fe006eaa English: Damage after Wowhead's guides, an alternative to the recommended Icy Veins
--     damage premade, off by default: enable it and disable that one, or raise its priority. Mind
--     Blast opens and goes before DoT refreshes, Vampiric Embrace only when your health drops, and
--     a dying target gets spells instead of the wand. Otherwise the same as the recommended
--     premade.
[1782] = "Danni secondo le guide di Wowhead, un'alternativa alla rotazione integrata consigliata da danni di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Detonazione Mentale apre e viene prima del rinnovo dei danni periodici, Abbraccio Vampirico solo quando la tua salute cala, e un bersaglio in punto di morte riceve incantesimi invece della bacchetta. Per il resto è uguale alla rotazione integrata consigliata.",
-- d0f0e9e6 English: Healer (Wowhead)
[1783] = "Guaritore (Wowhead)",
-- d31781e0 English: Healing in a group when Holy or Discipline is your main talent tree. It advises
--     on the friendly unit you target; you choose whom to heal. Prayer of Mending before pulls and
--     whenever ready, Renew, Power Word: Shield in emergencies, dispels, Circle of Healing or
--     Prayer of Healing for group damage, Binding, Flash and Greater Heal, and Greater Heal rank 1
--     as a cheap top-up. With an enemy targeted it offers light damage.
[1784] = "Cure in gruppo quando Sacro o Disciplina è il tuo albero dei talenti principale. Consiglia in base all'unità amica che hai come bersaglio; scegli tu chi curare. Preghiera di Guarigione prima degli ingaggi e ogni volta che è pronta, Rinnovamento, Parola del Potere: Scudo nelle emergenze, dissoluzioni, Cerchio di Guarigione o Preghiera di Cura per i danni al gruppo, Cura Combinata, Cura Rapida e Cura Superiore, e Cura Superiore di grado 1 come rabbocco economico. Con un nemico come bersaglio propone qualche danno leggero.",
-- 45321807 English: Healer (Icy Veins)
[1785] = "Guaritore (Icy Veins)",
-- e31d4277 English: Healing after Icy Veins' order: Shield, dispels, Binding Heal, Renew, Flash
--     Heal, Greater Heal (any rank), group heals, and Prayer of Mending last. You choose whom to
--     heal. An alternative to the recommended Wowhead healer premade, off by default: enable it and
--     disable that one, or raise its priority.
[1786] = "Cure secondo l'ordine di Icy Veins: Scudo, dissoluzioni, Cura Combinata, Rinnovamento, Cura Rapida, Cura Superiore (qualsiasi grado), cure di gruppo e per ultima Preghiera di Guarigione. Scegli tu chi curare. Un'alternativa alla rotazione integrata consigliata da guaritore di Wowhead, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità.",
-- 8283f17a English: All trees (Icy Veins)
[1787] = "Tutti gli alberi (Icy Veins)",
-- da4da042 English: Every talent tree from level 1 to 70. Curse, then Unstable Affliction,
--     Immolate, Corruption and Siphon Life as learned, Shadow Bolt or Incinerate; Nightfall and
--     Backlash procs first; Seed, Hellfire and Shadowfury for three or more enemies. Solo it drains
--     when hurt, Life Taps, wands, and uses Drain Soul or a finisher on a dying target. Reminders:
--     Fel Armor, Demon Armor or Demon Skin, your demon, sacrifice, Soul Link, Amplify Curse and
--     Soulshatter. Fears and other curses stay with you.
[1788] = "Ogni albero dei talenti dal livello 1 al 70. Maledizione, poi Afflizione Instabile, Immolazione, Corruzione e Sifone di Vita man mano che li apprendi, Dardo d'Ombra o Incenerimento; prima gli effetti di Calar della Notte e Contraccolpo; Seme della Corruzione, Fuoco Infernale e Furia dell'Ombra contro tre o più nemici. Da solo usa i risucchi quando sei ferito, Conversione Vitale, la bacchetta, e Risucchio d'Anima o un colpo di grazia su un bersaglio in punto di morte. Promemoria: Armatura Vile, Armatura Demoniaca o Pelle Demoniaca, il tuo demone, il sacrificio, Legame d'Anima, Amplifica Maledizione e Frantumazione d'Anima. Paure e altre maledizioni restano a te.",
-- e3790b25 English: Drain-tank (Wowhead)
[1789] = "Risucchio difensivo (Wowhead)",
-- 522ed69f English: Warlock after Wowhead's guides, an alternative to the recommended Icy Veins
--     Warlock premade, off by default: enable it and disable that one, or raise its priority. Solo
--     it drain-tanks: Drain Life is the filler once your DoTs are up and Immolate and Siphon Life
--     are kept for elite mobs. In a group Immolate always goes on, after Corruption and Siphon
--     Life. Otherwise the same as the recommended premade.
[1790] = "Stregone secondo le guide di Wowhead, un'alternativa alla rotazione integrata consigliata dello Stregone di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Da solo fa \"drain-tanking\": Risucchio di Vita è il riempitivo una volta attivi i tuoi danni periodici, e Immolazione e Sifone di Vita sono riservati ai mostri élite. In gruppo Immolazione va sempre applicata, dopo Corruzione e Sifone di Vita. Per il resto è uguale alla rotazione integrata consigliata.",
-- a97bc1c7 English: Apply changes to this selected item list. Other settings keep their own Apply
--     action.
[1791] = "Applica le modifiche a questo elenco di oggetti selezionato. Le altre impostazioni hanno una propria azione Applica.",
-- 4cec1d75 English: Choose an item list before editing.
[1792] = "Scegli un elenco di oggetti prima di modificarlo.",
-- 550c388b English: The item list changed elsewhere. Close and reopen it before applying.
[1793] = "L'elenco di oggetti è stato modificato altrove. Chiudilo e riaprilo prima di applicare.",
