[2850] = "Osservazione del famiglio con exists booleano e, per un famiglio presente richiesto, name; nil quando i dati richiesti non sono disponibili.",
-- f4bb093a English: Policy or availability reason for a nil movement observation.
[2851] = "Motivo di policy o di indisponibilità quando l'osservazione del movimento è nil.",
