[2865] = "Motivo di policy, di convalida della query o di indisponibilità di un'osservazione richiesta quando il record è nil.",
-- 6d8971dd English: Policy, query-validation or required-observation availability reason for a nil
--     ID.
[2866] = "Motivo di policy, di convalida della query o di indisponibilità di un'osservazione richiesta quando l'ID è nil.",
-- abb38505 English: Policy, query-validation or required-observation availability reason for a nil
--     match.
[2867] = "Motivo di policy, di convalida della query o di indisponibilità di un'osservazione richiesta quando la corrispondenza è nil.",
-- 4be03f57 English: Policy, slot-validation or required observation availability reason for a nil
--     type.
[2868] = "Motivo di policy, di convalida dello slot o di indisponibilità di un'osservazione richiesta quando il tipo è nil.",
-- 07a2f2a4 English: Policy, slot-validation, capability or native-call availability reason for a
--     nil record.
[2869] = "Motivo di policy, di convalida dello slot, di funzionalità o di indisponibilità della chiamata nativa quando il record è nil.",
-- 57d4e2a6 English: Policy, snapshot, identity or threat observation availability reason.
[2870] = "Motivo di policy o di indisponibilità dell'osservazione di istantanea, identità o minaccia.",
-- 88172c69 English: Policy, token-validation or availability reason for a nil identity result.
[2871] = "Motivo di policy, di convalida dell'identificativo o di indisponibilità quando il risultato dell'identità è nil.",
-- 41f7dc66 English: Policy, validation or availability reason for a nil health observation.
[2872] = "Motivo di policy, di convalida o di indisponibilità quando l'osservazione della salute è nil.",
-- cc67968e English: Policy, validation or availability reason for a nil snapshot.
[2873] = "Motivo di policy, di convalida o di indisponibilità quando l'istantanea è nil.",
-- 84bacc88 English: Policy, validation or observation availability reason.
[2874] = "Motivo di policy, di convalida o di indisponibilità dell'osservazione.",
-- 702b5d1d English: Policy, validation or required observation availability reason.
[2875] = "Motivo di policy, di convalida o di indisponibilità di un'osservazione richiesta.",
-- e3a0a3ce English: Positive integer glyph item ID stored by the condition; arrays, item-set keys
--     and spell IDs are not item references.
[2876] = "ID intero positivo dell'oggetto glifo memorizzato dalla condizione; array, chiavi dei set di oggetti e ID degli incantesimi non sono riferimenti a oggetti.",
-- c7e5f035 English: Positive integer level, false for a known absent unit, or nil when unavailable.
[2877] = "Livello intero positivo, false per un'unità accertata come assente, oppure nil se non disponibile.",
-- 2ce665d6 English: Positive integer spell ID, not a spell-book slot.
[2878] = "ID intero positivo dell'incantesimo, non uno slot del libro degli incantesimi.",
-- 37be242f English: Positive item ID or native-recognized item name/link to classify.
[2879] = "ID oggetto positivo o nome/link dell'oggetto riconosciuto dal client da classificare.",
-- eac23024 English: Predicate that validates the proposed spell value.
[2880] = "Predicato che convalida il valore proposto per l'incantesimo.",
-- b7acadb2 English: Present GUID, false for known absence, or nil when unavailable.
[2881] = "GUID presente, false per un'assenza accertata, oppure nil se non disponibile.",
-- 5825055c English: Provider, validation or observation availability reason.
[2882] = "Motivo di fornitore, di convalida o di indisponibilità dell'osservazione.",
-- e78c7309 English: Query, policy or observation availability reason.
[2883] = "Motivo di query, di policy o di indisponibilità dell'osservazione.",
-- b79b336b English: RM comparison operator identifier; missing labels use the operator placeholder.
[2884] = "Identificativo di operatore di confronto RM; le etichette mancanti usano il segnaposto dell'operatore.",
-- 505c9dde English: RM operator identifier.
[2885] = "Identificativo di operatore RM.",
-- a3bcccb3 English: Range record with applicable and, when applicable, inRange; nil when
--     unavailable.
[2886] = "Record di portata con applicable e, se applicabile, inRange; nil se non disponibile.",
-- a18d0c99 English: Read a fresh protected UnitClass player observation for rotation ownership.
--     Consume only the readable nonempty class filename from return two. No existence, level,
--     vehicle, family or combat-policy read is added, and no result persists across calls. Core
--     ownership still validates the class token and character key separately; overridden context
--     providers retain their complete original path.
[2887] = "Legge un'osservazione protetta e appena letta di UnitClass del giocatore per la proprietà della rotazione. Consuma solo il nome file della classe leggibile e non vuoto dal secondo valore restituito. Non vengono aggiunte letture di esistenza, livello, veicolo, famiglia o policy di combattimento, e nessun risultato persiste tra le chiamate. La proprietà nel nucleo convalida comunque separatamente l'identificativo della classe e la chiave del personaggio; i fornitori di contesto sostituiti mantengono il loro percorso originale completo.",
-- 97b3a051 English: Read a fresh protected zero-argument GetTime for rune cooldown arithmetic.
--     Require a readable finite number. This observation is deliberately uncached; callers preserve
--     the original clock-before-scan order and require its value only when a matching rune needs
--     timing. No evaluation-start substitution or inferred time is supplied.
[2888] = "Legge un GetTime protetto, appena letto e senza argomenti, per l'aritmetica dei tempi di recupero delle rune. Richiede un numero leggibile e finito. Questa osservazione non usa deliberatamente la cache; i chiamanti preservano l'ordine originale orologio-prima-della-scansione e richiedono il suo valore solo quando una runa corrispondente ha bisogno dei tempi. Non vengono forniti sostituzioni con l'inizio della valutazione né tempi dedotti.",
-- 3b2652a8 English: Read a lazy health scalar after a separate identity gate. Kind current uses
--     exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe- and restricted-policy
--     clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID
--     call or alternate tuple fallback is added.
[2889] = "Legge un valore scalare pigro della salute dopo un controllo separato dell'identità. Il tipo current usa esattamente UnitHealth(unit); maximum usa esattamente UnitHealthMax(unit). I client con policy di sondaggio o ristretta accettano numeri leggibili, finiti e non negativi, zero incluso. Non vengono aggiunte chiamate ripetute di esistenza/GUID né ripieghi su tuple alternative.",
-- cd858e26 English: Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime,
--     cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data
--     return nil with a reason.
[2890] = "Legge un record normalizzato delle cariche: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate e isActive. Incantesimi non supportati o dati del client soggetti a restrizioni restituiscono nil con un motivo.",
-- 3ba4fbdf English: Read a specified unit membership in the player party or raid. True raidOnly
--     queries only UnitInRaid; otherwise a true UnitInParty result short-circuits, false proceeds
--     to UnitInRaid, and unknown remains unavailable. Readable nil raid index means false; integer
--     raid index1..40 means true. Names are passed unchanged to native APIs; native name-query
--     acceptance requires client qualification.
[2891] = "Legge l'appartenenza di un'unità specificata al gruppo o all'incursione del giocatore. Con raidOnly true interroga solo UnitInRaid; altrimenti un risultato true di UnitInParty termina subito, false passa a UnitInRaid e un valore sconosciuto resta non disponibile. Un indice di incursione nil leggibile significa false; un indice intero da 1 a 40 significa true. I nomi vengono passati invariati alle API native; l'accettazione delle query per nome da parte delle API native richiede la qualificazione del client.",
-- 3db7feb7 English: Read and normalize a spell cooldown across supported clients. The returned
--     record contains startTime, duration, isEnabled and modRate. The timestamps and duration
--     already describe expiration in GetTime() seconds; do not divide them by modRate. When the
--     client hides the times (Retail and Forever in combat) the record is nil with reason
--     restricted-value, followed by the never-secret isEnabled, isActive and isOnGCD flags when
--     they can be read.
[2892] = "Legge e normalizza il tempo di recupero di un incantesimo su tutti i client supportati. Il record restituito contiene startTime, duration, isEnabled e modRate. Gli istanti e la durata descrivono già la scadenza in secondi di GetTime(); non dividerli per modRate. Quando il client nasconde i tempi (Retail e Forever in combattimento) il record è nil con motivo restricted-value, seguito dai flag isEnabled, isActive e isOnGCD, mai segreti, quando possono essere letti.",
-- 4ae0aa42 English: Read normalized native item classification metadata. The record contains
--     canonical itemID, classID and subClassID, plus equipLoc, the non-localized INVTYPE_* equip
--     location token, when it is readable and nonempty; it does not require loaded item display
--     text. Missing, failed, malformed or restricted metadata returns nil with a reason.
[2893] = "Legge i metadati nativi normalizzati di classificazione dell'oggetto. Il record contiene itemID, classID e subClassID canonici, oltre a equipLoc, il token INVTYPE_* non localizzato della posizione di equipaggiamento, quando è leggibile e non vuoto; non richiede che il testo visualizzato dell'oggetto sia caricato. I metadati mancanti, non riusciti, malformati o limitati restituiscono nil con un motivo.",
-- 5286a3fe English: Read one documented active loss-of-control row by its native index and
--     requested subject kind. Type queries require only the readable control type string; school
--     queries require only the readable finite nonnegative integer school mask. Optional timing is
--     returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject
--     does not require a usable timer. Missing rows are unavailable snapshot observations. No
--     display fields, inferred deadline, duration sum, maximum or native alias fallback is used.
[2894] = "Legge una riga documentata di perdita di controllo attiva tramite il suo indice nativo e il tipo di soggetto richiesto. Le query di tipo richiedono solo la stringa leggibile del tipo di controllo; le query di scuola richiedono solo la maschera di scuola leggibile, finita, intera e non negativa. La tempistica facoltativa viene restituita come timeRemaining finito o come motivo esplicito per campo, così un soggetto non correlato non richiede un timer utilizzabile. Le righe mancanti sono osservazioni non disponibili dell'istantanea. Non vengono usati campi di visualizzazione, scadenze dedotte, somme delle durate, massimi o ripieghi su alias nativi.",
-- 5a423c22 English: Read one explicitly selected point-resource quantity with an exact two-argument
--     UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or
--     actor remapping occurs. Preserve finite signed, fractional and zero quantities without
--     clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and
--     maximum are separate observations so callers can share current snapshots while requesting
--     maximum lazily.
[2895] = "Legge la quantità di una singola risorsa a punti selezionata esplicitamente, con una query esatta a due argomenti UnitPower o UnitPowerMax. Il selettore è obbligatorio; non avvengono deduzioni della risorsa primaria né rimappature dell'attore. Preserva le quantità finite con segno, frazionarie e zero senza limitarle. Dati mancanti, falliti, soggetti a restrizioni o non finiti restano non disponibili. Attuale e massimo sono osservazioni separate, così i chiamanti possono condividere le istantanee attuali richiedendo il massimo solo quando serve.",
-- 9f37d74c English: Read one protected GetRuneCooldown tuple for an exact native slot. Normalize
--     ready, start and duration independently: ready requires a readable Boolean, while each time
--     requires a readable finite number and preserves signed, fractional and zero values. Every
--     unavailable field carries its own reason. A successful empty tuple yields a partial record;
--     missing capability, policy or native-call failure yields nil. Never infer ready from timing
--     or timing from ready. Cache this complete record at the caller to share one observation
--     between rune-count and cooldown predicates.
[2896] = "Legge una singola tupla protetta di GetRuneCooldown per uno slot nativo esatto. Normalizza ready, start e duration in modo indipendente: ready richiede un booleano leggibile, mentre ogni tempo richiede un numero leggibile e finito e preserva i valori con segno, frazionari e zero. Ogni campo non disponibile ha il proprio motivo. Una tupla vuota restituita con successo produce un record parziale; funzionalità mancante, policy o errore della chiamata nativa producono nil. Non dedurre mai ready dai tempi né i tempi da ready. Memorizza in cache questo record completo nel chiamante per condividere una sola osservazione tra i predicati di conteggio delle rune e di tempo di recupero.",
-- 0ab0e9af English: Read optional MobInfo2 historical observations on probe- and restricted-policy
--     clients. Cache only exact selected-unit presence; UnitName result one, UnitLevel result one
--     and the three-argument MI2_GetMobData(name,level,unit) dot call stay fresh each invocation.
--     Known absent units and successful unrecorded nil or omitted history remain distinct from
--     unavailable native/provider facts. Preserve readable runner scalar truthiness, school signs
--     and missing-Hits default one. Positive resistance ratios must be finite; complete immunity
--     consumes finite Hits while partial immunity needs only its negative school observation. Never
--     infer native resistance or borrow old records.
[2897] = "Legge le osservazioni storiche facoltative di MobInfo2 sui client con policy di sondaggio o ristretta. Memorizza in cache solo la presenza esatta dell'unità selezionata; il primo risultato di UnitName, il primo risultato di UnitLevel e la chiamata con punto a tre argomenti MI2_GetMobData(name,level,unit) vengono rieseguiti a ogni chiamata. Le unità accertate come assenti e una cronologia nil o omessa restituita con successo restano distinte dai dati nativi/del fornitore non disponibili. Preserva la veridicità dello scalare runner leggibile, i segni delle scuole e il valore predefinito uno per Hits mancante. I rapporti di resistenza positivi devono essere finiti; l'immunità completa consuma Hits finito, mentre l'immunità parziale richiede solo l'osservazione negativa della propria scuola. Non dedurre mai la resistenza nativa né prendere in prestito record vecchi.",
-- a27fc0e3 English: Read optional RealMobHealth using its exact one-argument dot call. Absent
--     nil/false namespace returns an empty record. Normalize current and maximum independently:
--     nil/false fields permit native fallback, numeric zero remains present. Malformed, failed,
--     restricted, negative or nonfinite consumed provider facts are unavailable. No provider or
--     stale fallback cache is used.
[2898] = "Legge RealMobHealth facoltativo usando la sua chiamata con punto esatta a un argomento. Uno spazio dei nomi assente nil/false restituisce un record vuoto. Normalizza attuale e massimo in modo indipendente: i campi nil/false consentono il ripiego nativo, lo zero numerico resta presente. Dati del fornitore consumati malformati, falliti, soggetti a restrizioni, negativi o non finiti sono non disponibili. Non viene usata alcuna cache di ripiego del fornitore o obsoleta.",
-- 0a7395cc English: Read public group membership on identified client families. Unknown clients are
--     unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native
--     default group category. A readable false result stays false. Missing, failed, malformed or
--     restricted observations return nil with a reason.
[2899] = "Legge l'appartenenza pubblica al gruppo sulle famiglie di client identificate. I client sconosciuti non sono supportati. Con raidOnly true controlla IsInRaid; con false o nil controlla IsInGroup usando la categoria di gruppo nativa predefinita. Un risultato false leggibile resta false. Osservazioni mancanti, fallite, malformate o soggette a restrizioni restituiscono nil con un motivo.",
-- 4a264ad3 English: Read public roster identity on identified client families. Input routing is
--     limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that
--     exact one-argument token first; known false returns false without querying class. For a
--     present unit, consume only UnitClass return two as a readable nonempty class filename string,
--     without a class enum restriction. Missing, failed, malformed or restricted required facts
--     return nil with a reason.
[2900] = "Legge l'identità pubblica dei membri sulle famiglie di client identificate. L'instradamento degli input è limitato a player, da party1 a party4 e da raid1 a raid40. Chiama prima UnitExists con quell'esatto identificativo come unico argomento; un false accertato restituisce false senza interrogare la classe. Per un'unità presente, consuma solo il secondo valore restituito da UnitClass come stringa leggibile e non vuota del nome file della classe, senza limitarla a un enum di classi. Dati richiesti mancanti, falliti, malformati o soggetti a restrizioni restituiscono nil con un motivo.",
-- 1f3c0a57 English: Read spell-specific range for a unit using the appropriate client API or
--     spell-book slot. A spell without a range restriction returns applicable=false; otherwise
--     applicable=true and inRange records whether the unit is in range. Unknown or inaccessible
--     observations return nil with a reason.
[2901] = "Legge la portata specifica di un incantesimo per un'unità usando l'API del client appropriata o lo slot del libro degli incantesimi. Un incantesimo senza limite di portata restituisce applicable=false; altrimenti applicable=true e inRange indica se l'unità è entro portata. Osservazioni sconosciute o inaccessibili restituiscono nil con un motivo.",
-- d3d07abb English: Read the current positive nameplate visibility distance using the supported
--     CVar API. This limits a Distance Count query; it does not prove that all nearby units have
--     been observed. Missing, malformed, restricted or failed observations return nil with a
--     reason.
[2902] = "Legge l'attuale distanza positiva di visibilità delle targhette usando l'API CVar supportata. Limita una query di Conteggio distanza; non dimostra che tutte le unità vicine siano state osservate. Osservazioni mancanti, malformate, soggette a restrizioni o fallite restituiscono nil con un motivo.",
-- f4bc8da4 English: Read the documented active loss-of-control count with a protected zero-argument
--     dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and
--     does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that
--     resource budget; this is not a declared native maximum. Required missing, failed, restricted
--     or malformed observations remain unavailable.
[2903] = "Legge il conteggio documentato delle perdite di controllo attive con una chiamata con punto protetta senza argomenti. Richiede un intero leggibile, finito e non negativo. Zero è una scansione vuota completa e non richiede un'API per le righe. RM limita una scansione a 256 righe e oltre questo budget restituisce non disponibile; non si tratta di un massimo nativo dichiarato. Osservazioni richieste mancanti, fallite, soggette a restrizioni o malformate restano non disponibili.",
-- 597a72b9 English: Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This
--     is distinct from a current or queued cast. Modern clients receive the exact spell ID; a
--     legacy query resolves the player spell-book slot first. Restricted client policies,
--     unreadable results and unavailable book slots return nil with a reason. This observes state
--     and never starts or stops a spell.
[2904] = "Legge lo stato di ripetizione automatica del giocatore per un incantesimo come Shoot o Auto Shot. È distinto da un lancio attuale o in coda. I client moderni ricevono l'ID esatto dell'incantesimo; una query del sistema precedente risolve prima lo slot del libro degli incantesimi del giocatore. Policy del client con restrizioni, risultati illeggibili e slot del libro non disponibili restituiscono nil con un motivo. Osserva lo stato e non avvia né interrompe mai un incantesimo.",
-- 89759fd9 English: Read the public LibRangeCheck interval for a unit. A successful upper bound is
--     inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither
--     bound is an exact distance, and a missing upper bound is not proof that the unit is outside
--     every radius. Unavailable, malformed, restricted or failed observations return nil with a
--     reason.
[2905] = "Legge l'intervallo pubblico di LibRangeCheck per un'unità. Un limite superiore riuscito è inclusivo; un limite inferiore positivo non riuscito è stretto. Un limite inferiore pari a zero è sintetico. Nessuno dei due limiti è una distanza esatta, e l'assenza di un limite superiore non prova che l'unità sia al di fuori di ogni raggio. Osservazioni non disponibili, malformate, soggette a restrizioni o fallite restituiscono nil con un motivo.",
-- 41e0213a English: Readability authority for consumed values.
[2906] = "Autorità di leggibilità per i valori consumati.",
-- 7f7e5283 English: Readable canonical item classification record (itemID, classID, subClassID and
--     optional equipLoc), or nil when unavailable.
[2907] = "Record canonico e leggibile di classificazione dell'oggetto (itemID, classID, subClassID ed equipLoc facoltativo), oppure nil se non disponibile.",
-- 708f11a6 English: Readable canonical itemID/classID/subClassID record when the item is a glyph
--     for the requested class; nil for invalid or unavailable metadata.
[2908] = "Record canonico leggibile itemID/classID/subClassID quando l'oggetto è un glifo per la classe richiesta; nil per metadati non validi o non disponibili.",
-- b7b27422 English: Readable charge record, or nil when unavailable.
[2909] = "Record leggibile delle cariche, oppure nil se non disponibile.",
-- 5274b7b7 English: Readable consumed metadata string, false for a known absent unit, or nil when
--     required data is unavailable.
[2910] = "Stringa leggibile dei metadati consumati, false per un'unità accertata come assente, oppure nil quando i dati richiesti non sono disponibili.",
-- 041c7f05 English: Readable cooldown record, or nil when unavailable.
[2911] = "Record leggibile del tempo di recupero, oppure nil se non disponibile.",
-- c171ab16 English: Readable current state, or nil when unavailable.
[2912] = "Stato attuale leggibile, oppure nil se non disponibile.",
-- ea709ff8 English: Readable finite current-form observation, including zero for the current
--     unshifted comparison; nil when unavailable.
[2913] = "Osservazione leggibile e finita della forma attuale, zero incluso per il confronto con la forma normale attuale; nil se non disponibile.",
-- 5fe2cef3 English: Readable finite positive integral rune type, or nil when unavailable.
[2914] = "Tipo di runa leggibile, finito, intero e positivo, oppure nil se non disponibile.",
-- 243ee644 English: Readable interval with optional minimum and maximum bounds in yards. At least
--     one bound is present; nil when unavailable.
[2915] = "Intervallo leggibile con limiti minimo e massimo facoltativi in metri. È presente almeno un limite; nil se non disponibile.",
-- 7c9763dd English: Readable nonempty selected unit token, passed unchanged as the single argument
--     to existence and creature metadata queries.
[2916] = "Identificativo leggibile e non vuoto dell'unità selezionata, passato invariato come unico argomento alle query di esistenza e di metadati della creatura.",
-- 2ce03ebb English: Readable nonempty unit token or native-recognized name, passed unchanged.
[2917] = "Identificativo unità leggibile e non vuoto o nome riconosciuto dal client, passato invariato.",
-- 30a14f21 English: Readable nonempty unit token to match, unchanged in the native observation.
[2918] = "Identificativo unità leggibile e non vuoto da confrontare, invariato nell'osservazione nativa.",
-- 4421ce67 English: Readable nonempty unit token, passed unchanged as the single native argument.
[2919] = "Identificativo unità leggibile e non vuoto, passato invariato come unico argomento nativo.",
-- 831ff884 English: Readable record with Boolean exists and the requested class filename when
--     present; nil when required data is unavailable.
[2920] = "Record leggibile con exists booleano e, se presente, il nome file della classe richiesto; nil quando i dati richiesti non sono disponibili.",
-- e5d5a0bd English: Readable selected flag or nil when required data is unavailable.
[2921] = "Indicatore selezionato leggibile, oppure nil quando i dati richiesti non sono disponibili.",
-- ae99174e English: Readable selected flag, false for a known absent unit, or nil when a required
--     observation is unavailable.
[2922] = "Indicatore selezionato leggibile, false per un'unità accertata come assente, oppure nil quando un'osservazione richiesta non è disponibile.",
-- 15d71981 English: Readable unit equality, false for a known absent first unit, or nil when
--     required observations are unavailable.
[2923] = "Uguaglianza leggibile tra unità, false se la prima unità è accertata come assente, oppure nil quando le osservazioni richieste non sono disponibili.",
-- c72ce8bc English: Record with exists=false, or exists=true and finite value; nil when
--     unavailable.
[2924] = "Record con exists=false, oppure exists=true e un valore finito; nil se non disponibile.",
-- bbdbf34c English: Record with exists=false; recorded=false for known no history; or runner,
--     ratio, or immune with hits/hitsReason. Nil means a required observation is unavailable.
[2925] = "Record con exists=false; recorded=false se è accertata l'assenza di cronologia; oppure runner, ratio o immune con hits/hitsReason. Nil indica che un'osservazione richiesta non è disponibile.",
-- d2443dc7 English: Record with inInstance and, when inside, instanceType or instanceTypeReason;
--     nil when membership is unavailable.
[2926] = "Record con inInstance e, se all'interno, instanceType o instanceTypeReason; nil quando l'appartenenza non è disponibile.",
-- b2c4007b English: Reference input kind, such as Spec_EditBox, used for spell suggestions.
[2927] = "Tipo di input di riferimento, ad esempio Spec_EditBox, usato per i suggerimenti degli incantesimi.",
-- 27542d97 English: Remove entries in place, preserving only keys listed among except values by
--     default. With invert true, remove listed keys and retain unlisted keys. Without an exception
--     list, the default removes every entry and invert true retains every entry. Nil input does
--     nothing.
[2928] = "Rimuove voci sul posto, mantenendo per impostazione predefinita solo le chiavi elencate tra i valori di except. Con invert true rimuove le chiavi elencate e mantiene quelle non elencate. Senza un elenco di eccezioni, l'impostazione predefinita rimuove tutte le voci e invert true le mantiene tutte. Un input nil non fa nulla.",
-- e6ab096c English: Remove leading and trailing Lua-pattern whitespace from a string.
[2929] = "Rimuove da una stringa gli spazi iniziali e finali secondo i pattern Lua.",
-- a3fc9f6e English: Resolve a readable raw unit level for condition evaluation. Known absence
--     returns false; unavailable observations return nil with a reason. Cache observations within
--     the supplied evaluation pass. Only valid player levels are retained between passes until a
--     skill, profile or level refresh.
[2930] = "Risolve un livello grezzo leggibile dell'unità per la valutazione delle condizioni. Un'assenza accertata restituisce false; le osservazioni non disponibili restituiscono nil con un motivo. Memorizza in cache le osservazioni all'interno del passaggio di valutazione fornito. Tra un passaggio e l'altro vengono mantenuti solo i livelli validi del giocatore, fino a un aggiornamento di abilità, profilo o livello.",
-- 1be3efe7 English: Resolve an exact cast-recipient name against the current bounded party or raid
--     roster, then observe membership through a unit token. Missing, ambiguous or changing roster
--     data remains unavailable; never reads the selected target or retains state across casts.
[2931] = "Risolve il nome esatto del destinatario di un lancio rispetto all'elenco limitato attuale dei membri del gruppo o dell'incursione, poi osserva l'appartenenza tramite un identificativo unità. Dati dei membri mancanti, ambigui o in cambiamento restano non disponibili; non legge mai il bersaglio selezionato né mantiene stato tra un lancio e l'altro.",
-- bf87a408 English: Resolve point resources using the original live class mapping and identity
--     cache, with an explicit TBC player ComboPoints-fallback transport policy. A player fallback
--     matching the readable raw Enum.PowerType table and ComboPoints value captured at module load
--     selects target-combo; explicit class-map entries, other actors and other families retain
--     power. Replaced, inherited or unprovable fallback provenance retains power. This versioned
--     policy does not claim native UnitPower is broken or equivalent. Known unit absence returns
--     false; unavailable required observations return nil with a reason. No current or maximum
--     quantity is queried here.
[2932] = "Risolve le risorse a punti usando la corrispondenza originale attuale delle classi e la cache dell'identità, con una policy di trasporto esplicita di ripiego su ComboPoints per il giocatore di TBC. Un ripiego del giocatore che corrisponde alla tabella grezza leggibile Enum.PowerType e al valore ComboPoints acquisiti al caricamento del modulo seleziona target-combo; le voci esplicite della mappa delle classi, gli altri attori e le altre famiglie mantengono power. Un ripiego sostituito, ereditato o di provenienza non dimostrabile mantiene power. Questa policy versionata non afferma che UnitPower nativo sia difettoso o equivalente. Un'unità accertata come assente restituisce false; osservazioni richieste non disponibili restituiscono nil con un motivo. Qui non viene interrogata alcuna quantità attuale o massima.",
-- b9173e02 English: Resolve the selected unit point-resource selector using the live
--     class-to-resource map and ComboPoints fallback. Known absence returns false; unavailable
--     required identity or selector data returns nil with a reason. Share complete identity
--     observations within the evaluation pass. Only successful player class observations persist in
--     the current longterm cache, tied to the native UnitClass identity; existence is refreshed
--     each pass. This selects a resource without reading its current or maximum quantity.
[2933] = "Risolve il selettore delle risorse a punti dell'unità selezionata usando la mappa attuale classe-risorsa e il ripiego su ComboPoints. Un'assenza accertata restituisce false; dati di identità o del selettore richiesti non disponibili restituiscono nil con un motivo. Condivide le osservazioni complete dell'identità all'interno del passaggio di valutazione. Solo le osservazioni riuscite della classe del giocatore persistono nella cache a lungo termine attuale, legate all'identità nativa di UnitClass; l'esistenza viene aggiornata a ogni passaggio. Seleziona una risorsa senza leggerne la quantità attuale o massima.",
-- 718644e5 English: Resolve the spell identifier stored by a condition. With exact rank enabled the
--     supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank
--     through the spell catalog. Returns nil and an availability reason if resolution cannot be
--     completed.
[2934] = "Risolve l'identificatore dell'incantesimo memorizzato da una condizione. Con il grado esatto attivato, l'ID fornito viene mantenuto; altrimenti i client Classic con gradi risolvono il grado attualmente conosciuto tramite il catalogo degli incantesimi. Restituisce nil e un motivo di indisponibilità se la risoluzione non può essere completata.",
-- 1d0d55d1 English: Resolved spell ID, or nil when unavailable.
[2935] = "ID dell'incantesimo risolto, oppure nil se non disponibile.",
-- 6ffafa71 English: Resolver mapping a typed spell name to its ID.
[2936] = "Risolutore che associa un nome di incantesimo digitato al suo ID.",
-- 09cbb92e English: Return a present value unchanged, or a red display placeholder for nil. Use for
--     readable condition labels, not as a boolean fallback.
[2937] = "Restituisce invariato un valore presente, oppure un segnaposto rosso di visualizzazione per nil. Da usare per etichette leggibili delle condizioni, non come ripiego booleano.",
-- d42a9ff5 English: Return the first key whose value equals the supplied value during pairs
--     traversal. Nil or false input tables and absent values return nil. Multiple matching keys
--     have no guaranteed selection order.
[2938] = "Restituisce la prima chiave il cui valore è uguale al valore fornito durante l'attraversamento con pairs. Tabelle di input nil o false e valori assenti restituiscono nil. Se più chiavi corrispondono, l'ordine di selezione non è garantito.",
-- 3f5f3e62 English: Right operand; DIVISIBLE requires a nonzero divisor.
[2939] = "Operando destro; DIVISIBLE richiede un divisore diverso da zero.",
-- 6734885b English: Rotation Master addon instance (implicit with colon calls).
[2940] = "Istanza dell'addon Rotation Master (implicita nelle chiamate con due punti).",
-- 46daa133 English: Rotation Master platform adapter (implicit with colon calls).
[2941] = "Adattatore di piattaforma di Rotation Master (implicito nelle chiamate con due punti).",
-- f0f9c415 English: Rotation Master platform adapter. A dot reference requires addon.Platform as
--     the first argument; a colon call supplies it implicitly.
[2942] = "Adattatore di piattaforma di Rotation Master. Un riferimento con punto richiede addon.Platform come primo argomento; una chiamata con due punti lo fornisce implicitamente.",
-- 3f1284ef English: Round with the existing floor(num * 10^places + 0.5) / 10^places formula.
--     Places defaults to zero and may be negative. Halfway negative values round toward positive
--     infinity; no finite-number validation or alternative rounding policy is added.
[2943] = "Arrotonda con la formula esistente floor(num * 10^places + 0.5) / 10^places. Places è zero per impostazione predefinita e può essere negativo. I valori negativi a metà vengono arrotondati verso più infinito; non vengono aggiunte una convalida dei numeri finiti né criteri di arrotondamento alternativi.",
-- 885bcca4 English: Run the historical health-snapshot trend formula using the live profile history
--     window, clock and legacy rounding service. Preserve its maximum-health transitions, early
--     stop at full or zero health, weighting, errors and return counts. An empty array, or
--     snapshots that record no weighted change, return only zero rather than a 0/0 result; this is
--     the legacy algorithm rather than a validated forecast.
[2944] = "Esegue la formula storica di tendenza delle istantanee della salute usando la finestra attuale della cronologia del profilo, l'orologio e il servizio di arrotondamento precedente. Preserva le sue transizioni della salute massima, l'arresto anticipato a salute piena o nulla, la ponderazione, gli errori e il numero di valori restituiti. Un array vuoto, o istantanee che non registrano alcuna variazione ponderata, restituiscono solo zero invece di un risultato 0/0; è l'algoritmo precedente, non una previsione convalidata.",
-- 472af904 English: Second exact unit token, passed unchanged to UnitIsUnit.
[2945] = "Secondo identificativo unità esatto, passato invariato a UnitIsUnit.",
-- 89bc8587 English: Second table to compare.
[2946] = "Seconda tabella da confrontare.",
-- 181d7eb2 English: Selected nonempty unit token, unchanged in native calls.
[2947] = "Identificativo unità selezionato non vuoto, invariato nelle chiamate native.",
-- ad96e1f2 English: Selected nonempty unit token, unchanged in native/provider calls.
[2948] = "Identificativo unità selezionato non vuoto, invariato nelle chiamate native/del fornitore.",
-- 0fe63d0e English: Selected nonempty unit token.
[2949] = "Identificativo unità selezionato non vuoto.",
-- 2228fc20 English: Selected nonempty unit token; this call alone does not establish presence.
[2950] = "Identificativo unità selezionato non vuoto; questa chiamata da sola non stabilisce la presenza.",
-- f67a8632 English: Selected nonempty unit token; unchanged native argument.
[2951] = "Identificativo unità selezionato non vuoto; argomento nativo invariato.",
-- 9aeb1b04 English: Selected unit token forwarded as the only provider argument.
[2952] = "Identificativo unità selezionato, inoltrato come unico argomento del fornitore.",
-- 91d2e43e English: Selected unit token, unchanged in observations.
[2953] = "Identificativo unità selezionato, invariato nelle osservazioni.",
-- 169d575d English: Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and
--     callbacks.
[2954] = "Widget selettore che supporta SetList, SetValue, SetLabel, SetDisabled e le callback.",
-- c4649a76 English: Shared evaluation cache; nil observes directly without a per-pass cache.
[2955] = "Cache di valutazione condivisa; con nil osserva direttamente senza cache per passaggio.",
-- 32b53cb5 English: Source array whose ipairs prefix is inserted without copying nested values.
[2956] = "Array di origine il cui prefisso ipairs viene inserito senza copiare i valori annidati.",
-- f292d1c8 English: Specialization scope used to resolve spell suggestions.
[2957] = "Ambito di specializzazione usato per risolvere i suggerimenti degli incantesimi.",
-- 78f0e3c1 English: Spell ID or client-recognized spell name whose charges should be read.
[2958] = "ID dell'incantesimo o nome riconosciuto dal client di cui leggere le cariche.",
-- 3b34f727 English: Spell ID or client-recognized spell name whose cooldown should be checked.
[2959] = "ID dell'incantesimo o nome riconosciuto dal client di cui controllare il tempo di recupero.",
-- 2d3ce2ab English: Spell ID or client-recognized spell name whose cooldown should be read.
[2960] = "ID dell'incantesimo o nome riconosciuto dal client di cui leggere il tempo di recupero.",
-- 55538bf5 English: Spell ID whose range should be checked.
[2961] = "ID dell'incantesimo di cui controllare la portata.",
-- b7614a02 English: Spell field group containing an action icon, reference input and optional rank
--     control.
[2962] = "Gruppo di campi incantesimo contenente un'icona di azione, un input di riferimento e un controllo facoltativo del grado.",
-- 31f8edf3 English: Spell-book scope: spell, pet or any.
[2963] = "Ambito del libro degli incantesimi: spell, pet o any.",
-- 05372e4c English: Split a string into nonempty runs between separator characters. The separator
--     is inserted into a Lua pattern character class; it is not a literal multi-character
--     delimiter. Empty fields are omitted.
[2964] = "Divide una stringa in sequenze non vuote tra i caratteri separatori. Il separatore viene inserito in una classe di caratteri di un pattern Lua; non è un delimitatore letterale di più caratteri. I campi vuoti vengono omessi.",
-- db7ca748 English: Stored spell ID to resolve.
[2965] = "ID dell'incantesimo memorizzato da risolvere.",
-- 9379f3fe English: Successful observation record with pvpType string or nil; nil record means
--     unavailable.
[2966] = "Record di osservazione riuscita con stringa pvpType o nil; un record nil indica non disponibile.",
-- e41b12b3 English: Table to copy shallowly, or nil.
[2967] = "Tabella da copiare in modo superficiale, oppure nil.",
-- 07e8d4d0 English: Table to count, or nil for zero.
[2968] = "Tabella da contare, oppure nil per zero.",
-- 58e2d717 English: Table to inspect.
[2969] = "Tabella da esaminare.",
-- 90809a03 English: Table to modify, or nil to do nothing.
[2970] = "Tabella da modificare, oppure nil per non fare nulla.",
-- ff2b1485 English: Table to search; nil or false returns nil.
[2971] = "Tabella in cui cercare; nil o false restituisce nil.",
-- 259ede57 English: Table to traverse; keys must be mutually comparable when no custom ordering is
--     supplied.
[2972] = "Tabella da attraversare; le chiavi devono essere confrontabili tra loro quando non viene fornito un ordinamento personalizzato.",
-- f4e4becf English: Table whose keys should be converted to strings.
[2973] = "Tabella le cui chiavi devono essere convertite in stringhe.",
-- a59c785e English: Table whose values must be mutually comparable.
[2974] = "Tabella i cui valori devono essere confrontabili tra loro.",
-- 2074ad97 English: Target line width, default 72 characters.
[2975] = "Larghezza di riga desiderata, predefinita 72 caratteri.",
-- f3db5e09 English: Test a literal byte prefix using a Lua string slice. Empty prefixes match;
--     pattern characters have no special meaning and case is preserved.
[2976] = "Verifica un prefisso letterale di byte usando una sottostringa Lua. I prefissi vuoti corrispondono; i caratteri dei pattern non hanno significato speciale e maiuscole e minuscole vengono rispettate.",
-- 1f02a40c English: Test a literal byte suffix using a Lua string slice. Empty suffixes match;
--     pattern characters have no special meaning and case is preserved.
[2977] = "Verifica un suffisso letterale di byte usando una sottostringa Lua. I suffissi vuoti corrispondono; i caratteri dei pattern non hanno significato speciale e maiuscole e minuscole vengono rispettate.",
-- e2c64484 English: Text or number shown after the comparison wording.
[2978] = "Testo o numero mostrato dopo la formulazione del confronto.",
-- 026b376c English: Text or number shown before the comparison wording.
[2979] = "Testo o numero mostrato prima della formulazione del confronto.",
-- b84e9fc7 English: Text to inspect.
[2980] = "Testo da esaminare.",
-- 95d67c5a English: Text to split.
[2981] = "Testo da dividere.",
-- a672408d English: Text to trim.
[2982] = "Testo da ripulire.",
-- 332756da English: Text to wrap.
[2983] = "Testo da mandare a capo.",
-- 33010633 English: Text widget supporting label, text, pending-edit and callback methods.
[2984] = "Widget di testo che supporta metodi per etichetta, testo, modifica in sospeso e callback.",
-- f6be6e89 English: Text with line breaks inserted at word boundaries.
[2985] = "Testo con interruzioni di riga inserite ai confini delle parole.",
-- 6f85c46a English: The selected value, including false or nil.
[2986] = "Il valore selezionato, inclusi false o nil.",
-- 6af26a9c English: Transient trusted phrase recognized by condition summary rendering; do not
--     persist it as condition data.
[2987] = "Frase temporanea attendibile riconosciuta dalla generazione del riepilogo della condizione; non salvarla come dato della condizione.",
-- 2bae0b3f English: Transient typed predicate used as a named phrase value; do not persist it as
--     condition data.
[2988] = "Predicato tipizzato temporaneo usato come valore di una frase con nome; non salvarlo come dato della condizione.",
-- 4cf99d8d English: Trimmed text.
[2989] = "Testo ripulito.",
-- e0249036 English: True also observes maximum health; false or nil reads current health only.
[2990] = "True osserva anche la salute massima; false o nil legge solo la salute attuale.",
-- 9ba98a90 English: True also observes the selected resource maximum; false or nil reads current
--     quantity only.
[2991] = "True osserva anche il massimo della risorsa selezionata; false o nil legge solo la quantità attuale.",
-- 19d0b8a3 English: True also requires the present unit class filename; false reads existence only.
[2992] = "True richiede anche il nome file della classe dell'unità presente; false legge solo l'esistenza.",
-- ac4e613c English: True checks raid membership only; false or nil checks party or raid.
[2993] = "True controlla solo l'appartenenza all'incursione; false o nil controlla gruppo o incursione.",
-- 9cf4986d English: True checks raid membership only; false or nil checks party then raid.
[2994] = "True controlla solo l'appartenenza all'incursione; false o nil controlla il gruppo e poi l'incursione.",
-- 4bf4841d English: True for a readable attackable non-dead unit, false for a conclusive negative
--     result, or nil when a required observation is unavailable.
[2995] = "True per un'unità leggibile, attaccabile e non morta, false per un risultato negativo conclusivo, oppure nil quando un'osservazione richiesta non è disponibile.",
-- 72d71c8f English: True for an exact identity match; false for known absence or mismatch; nil when
--     required data or the query is unavailable.
[2996] = "True per una corrispondenza esatta di identità; false per assenza accertata o mancata corrispondenza; nil quando i dati richiesti o la query non sono disponibili.",
-- 3286d546 English: True includes only listed entries; false or nil excludes listed entries.
[2997] = "True include solo le voci elencate; false o nil esclude le voci elencate.",
-- b3108208 English: True marks the main comparison to negate; false or nil leaves it eligible only
--     when no primary predicate exists.
[2998] = "True indica il confronto principale da negare; false o nil lo lascia idoneo solo quando non esiste un predicato primario.",
-- 00d420e2 English: True permits the raid roster when raid membership is known true; false or nil
--     uses the solo or party roster.
[2999] = "True consente l'elenco dei membri dell'incursione quando l'appartenenza all'incursione è accertata; false o nil usa l'elenco in solitario o del gruppo.",
-- 9865f6c6 English: True removes listed entries; false or nil preserves only listed entries.
[3000] = "True rimuove le voci elencate; false o nil mantiene solo le voci elencate.",
-- 9e3983eb English: True requests raid membership; false or nil requests any group membership.
[3001] = "True richiede l'appartenenza a un'incursione; false o nil richiede l'appartenenza a qualsiasi gruppo.",
-- d660860e English: True requests the formatted pet name; false or omitted reads presence only.
[3002] = "True richiede il nome formattato del famiglio; false o omesso legge solo la presenza.",
-- d60dacff English: True selects percentage target and optional fresh provider facts.
[3003] = "True seleziona la salute bersaglio in percentuale e dati del fornitore facoltativi appena letti.",
-- 755a2020 English: True skips all access to the damage stream.
[3004] = "True salta qualsiasi accesso al flusso dei danni.",
-- 0ff2c956 English: True skips all access to the healing stream.
[3005] = "True salta qualsiasi accesso al flusso delle cure.",
-- e23b6035 English: True to require this exact rank; false or nil follows the available rank.
[3006] = "True per richiedere esattamente questo grado; false o nil segue il grado disponibile.",
-- bd4e75af English: True when array[value] is non-nil.
[3007] = "True quando array[value] non è nil.",
-- af070544 English: True when every visited entry compares equal in both directions.
[3008] = "True quando ogni voce visitata risulta uguale in entrambe le direzioni.",
-- 38e1fab8 English: True when ready by the end of the global cooldown; false when its own cooldown
--     prevents recommendation; nil when the client cannot supply a readable result.
[3009] = "True quando è pronto entro la fine del tempo di recupero globale; false quando il suo tempo di recupero ne impedisce la raccomandazione; nil quando il client non può fornire un risultato leggibile.",
-- 11ccb8e3 English: True when the client reports this spell auto-repeating; false when it reports
--     inactive; nil when unavailable.
[3010] = "True quando il client segnala che l'incantesimo si ripete automaticamente; false quando lo segnala inattivo; nil se non disponibile.",
-- 1b4d0696 English: Truthy skips the damage stream without reading its array.
[3011] = "Un valore truthy salta il flusso dei danni senza leggerne l'array.",
-- 09c7ad07 English: Truthy skips the heals stream without reading its array.
[3012] = "Un valore truthy salta il flusso delle cure senza leggerne l'array.",
-- 1a26aa88 English: Unit key-to-display-name map shown in the selector.
[3013] = "Mappa da chiave dell'unità a nome visualizzato, mostrata nel selettore.",
-- 72d92ef1 English: Unit token to compare with the literal player token.
[3014] = "Identificativo unità da confrontare con l'identificativo letterale player.",
-- a3b5e12b English: Unit token whose current cast or channel should be observed.
[3015] = "Identificativo dell'unità di cui osservare il lancio o l'incanalamento attuale.",
-- 8978c94b English: Unit token whose current health should be observed.
[3016] = "Identificativo dell'unità di cui osservare la salute attuale.",
-- 16f17c11 English: Unit token whose raw level should be observed.
[3017] = "Identificativo dell'unità di cui osservare il livello grezzo.",
-- bb787bde English: Unit token whose raw level should be resolved.
[3018] = "Identificativo dell'unità di cui risolvere il livello grezzo.",
-- 4b2caef5 English: Unit token, such as target; nil uses target.
[3019] = "Identificativo unità, ad esempio target; con nil usa target.",
-- 8b73a7bd English: Validation or availability reason for a nil result.
[3020] = "Motivo di convalida o di indisponibilità quando il risultato è nil.",
-- 193551e6 English: Validation, policy or availability reason for a nil result.
[3021] = "Motivo di convalida, di policy o di indisponibilità quando il risultato è nil.",
-- 2b8bf1ec English: Validation, policy or required-fact availability reason for a nil count.
[3022] = "Motivo di convalida, di policy o di indisponibilità di un dato richiesto quando il conteggio è nil.",
-- f4896f62 English: Value compared with each table value using Lua equality.
[3023] = "Valore confrontato con ciascun valore della tabella usando l'uguaglianza di Lua.",
-- 682b55a9 English: Value passed to the original arithmetic formula.
[3024] = "Valore passato alla formula aritmetica originale.",
-- 53d931f9 English: Value record field to edit; defaults to unit.
[3025] = "Campo del record del valore da modificare; predefinito unit.",
-- 48c786d6 English: Value returned for every other unit.
[3026] = "Valore restituito per ogni altra unità.",
-- 35f7fff6 English: Value returned when unit is player.
[3027] = "Valore restituito quando l'unità è player.",
-- 59731a4c English: Value to display; false is preserved.
[3028] = "Valore da visualizzare; false viene preservato.",
-- d488fb09 English: Visit entries in both tables and compare each value with the indexed value in
--     the other table using Lua equality. Normal indexing and equality metamethods apply; nested
--     contents are not compared recursively.
[3029] = "Visita le voci di entrambe le tabelle e confronta ogni valore con il valore allo stesso indice nell'altra tabella usando l'uguaglianza di Lua. Si applicano la normale indicizzazione e i metametodi di uguaglianza; i contenuti annidati non vengono confrontati ricorsivamente.",
-- b4707a12 English: Weighted health-snapshot change from the original total/count formula; zero for
--     falsy input or when no weighted change was recorded.
[3030] = "Variazione ponderata delle istantanee della salute secondo la formula originale totale/conteggio; zero per un input falso o quando non è stata registrata alcuna variazione ponderata.",
-- c3ba802c English: Weighting window in seconds; nil or false uses the current profile
--     damage_history setting.
[3031] = "Finestra di ponderazione in secondi; nil o false usa l'impostazione damage_history del profilo attuale.",
-- c6cfccd1 English: Whether the original floor-equality or exact numeric-spelling predicate
--     matches.
[3032] = "Indica se corrisponde il predicato originale di uguaglianza dopo floor o di rappresentazione numerica esatta.",
-- 8c0b7ad7 English: Whether the text begins with the exact prefix.
[3033] = "Indica se il testo inizia con il prefisso esatto.",
-- 37054b01 English: Whether the text ends with the exact suffix.
[3034] = "Indica se il testo termina con il suffisso esatto.",
-- 2ae8305f English: With restricted-value only: isActive, true while a cooldown (its own or the
--     global one) is running.
[3035] = "Solo con restricted-value: isActive, true mentre è in corso un tempo di recupero (il proprio o quello globale).",
-- 08c56f26 English: With restricted-value only: isEnabled, false while the cooldown is on hold.
[3036] = "Solo con restricted-value: isEnabled, false mentre il tempo di recupero è sospeso.",
-- 11f0d805 English: With restricted-value only: isOnGCD, true when the running cooldown is the
--     global cooldown; may be nil.
[3037] = "Solo con restricted-value: isOnGCD, true quando il tempo di recupero in corso è quello globale; può essere nil.",
-- 303e2b6b English: Work-limit, data or arithmetic availability reason for nil rate/age.
[3038] = "Motivo di indisponibilità per limite di lavoro, dati o aritmetica quando tasso/età è nil.",
-- 01efc08d English: Wrap text at whitespace boundaries near a target column count. Long words are
--     retained intact.
[3039] = "Manda a capo il testo in corrispondenza degli spazi vicino a un numero di colonne desiderato. Le parole lunghe vengono mantenute intere.",
-- 07e1e312 English: mana selects the explicit live Mana enum; current reads and forwards the actual
--     UnitPowerType identity, including Mana zero.
[3040] = "mana seleziona esplicitamente l'enum Mana attuale; current legge e inoltra l'identità effettiva di UnitPowerType, incluso Mana zero.",
-- c383f3b4 English: noheals selects damage only; nodmg selects healing only; other readable values
--     select both.
[3041] = "noheals seleziona solo i danni; nodmg seleziona solo le cure; altri valori leggibili selezionano entrambi.",
-- 02586670 English: Translation (%s): %s
[4043] = "Traduzione (%s): %s",
-- d607ecc3 English: Include disabled rotations
-- Context: Check box on the General settings page, Tooltips section. On: spell and item tooltips
--     also list rotations that are switched off (grayed, marked disabled). Off: only rotations that
--     are on are listed.
[4045] = "Includi le rotazioni disattivate",
-- e1738cc8 English: Exclude disabled conditions
-- Context: Check box on the General settings page, Tooltips section, next to 'Include rotation
--     conditions'. On: a condition that is switched off in the rotation editor is not counted when
--     tooltips list the rotations that use a spell or item.
[4046] = "Escludi le condizioni disattivate",
}
